import {mountReferencePicker} from './reference-picker.js';
import {GENDERS,healthValue,adjustHealth,imageKey,forgetMove,deleteRetiredPokemon,adjustItemQuantity} from './sheet-update.js';
import {mountSpeciesPicker} from './species-picker.js';
import {createCampaignUI} from './campaign-ui.js';
import {orderReferences} from './catalog-order.js';
import {filterCatalog,categoryNames} from './catalog-editor.js';
import {PERMANENT_VARIANTS,variantsFor,permanentVariant,permanentSpecies,setVariant} from './variants.js';
import {TYPES,MEGAS,gimmicks,activeMega,battleSpecies,battleStats,battleTypes,changeGimmick,convertedMove,effectiveMove} from './gimmicks.js';
import {request,seedEntries,applyCatalog,materializeAssets} from './catalog-client.js';
import {FLAVORS,potency,flavorTotals,flavorOptions,blockRecipe,describeBlock,prepareBlock} from './pokeblocks.js';
import {cultivationOutcome,plantBerry,endCultivationSession} from './greenhouse.js';
import {exportSheet,importSheet} from './transfer.js';
import {changeSpecies,retirePokemon,restorePokemon} from './collection.js';
import {migrate} from './migrate.js';
import {species,natures,moves,items,skills,art,itemArt,makePokemon,initialState,abilityCatalog} from './data.js';
import {rank,trust,stats,totalPE,hpDivisor,damage,accuracy,clamp,train,trainContest,combatValues,combatDT,activeLimit,STAT_LABELS} from './rules.js';
const hosted=location.protocol==='https:';
const $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={ball:'M3 12h6m6 0h6 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',person:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a8 8 0 0 1 16 0v3',bag:'M7 7V5a5 5 0 0 1 10 0v2 M5 7h14l1 14H4L5 7 M9 12h6',book:'M3 4h7a3 3 0 0 1 2 1 3 3 0 0 1 2-1h7v16h-7a3 3 0 0 0-2 1 3 3 0 0 0-2-1H3V4 M12 5v16',grid:'M3 3h7v7H3V3 M14 3h7v7h-7V3 M3 14h7v7H3v-7 M14 14h7v7h-7v-7',plus:'M12 5v14 M5 12h14',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',heart:'M12 20S2 14 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 6-10 12-10 12',leaf:'M20 3C5 1 1 9 6 16c7 7 16-1 14-13 M4 21 16 8',chevron:'M9 5l7 7-7 7',arrow:'M5 12h14 M13 6l6 6-6 6',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6',check:'m5 12 4 4L19 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',edit:'m15 4 5 5 M3 21l5-1L21 7l-5-5L3 15v6',close:'m6 6 12 12 M18 6 6 18',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 10v7 M12 7h.01',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5 M9 3v16 M15 5v16',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3',image:'M3 3h18v18H3V3 M3 17l6-6 4 4 3-3 5 5 M15 7h.01',spark:'m12 2 2 7 8 3-8 2-2 8-2-8-8-2 8-3 2-7',moon:'M21 13A9 9 0 1 1 11 3a7 7 0 0 0 10 10'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.ball}"/></svg>`;
const type=t=>`<span class="type" data-type="${escape(t)}">${escape(t)}</span>`;
const button=(action,label,style='secondary',ico='',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const bySpecies=id=>species.find(s=>s.id===Number(id))||species[0];
const byNature=id=>natures.find(n=>n.id===id)||natures[0];
const byMove=id=>moves.find(m=>m.id===id);
const allItems=()=>[...items,...(state?.customItems||[])];
const byItem=id=>allItems().find(i=>i.id===id);
const itemImage=i=>{const image=i?.image||(!i?.custom?itemArt(i.id):'');return image.replace(/(\/items\/[a-z]+ium-z)\.png$/, '$1--bag.png');};
const rankContent=c=>`${c.rank==='Básico'?'':`<img src="${itemArt(({'Poké Ball':'poke-ball','Great Ball':'great-ball','Ultra Ball':'ultra-ball','Master Ball':'master-ball'})[c.rank])}" alt="">`}<span><small>RANK</small>${c.rank}</span>`;
let state,db,saveTimer,toastTimer,saveQueue=Promise.resolve(),saveStatus='Salvo neste navegador';
let itemOrder='category',abilityOrder='name-en',inventoryOrder='category';
let inventoryTab='items',catalogTab='species',catalogQuery='',noteQuery='',noteDraft={id:'',title:'',text:''},contestTab='values',customItemImage='';
let view='pokemon',detailTab='overview',collectionFilter='all',collectionQuery='',inventoryQuery='',inventoryCategory='all';
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('jornada-rpg-prototipo',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function readState(){return new Promise((resolve,reject)=>{const req=db.transaction('state').objectStore('state').get('main');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function writeState(snapshot){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(snapshot,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function save(immediate=false){clearTimeout(saveTimer);setSaveStatus('Salvando…');const persist=()=>{const snapshot=structuredClone(state),target=connectedSheet;saveQueue=saveQueue.then(()=>{if(!db)throw Error('Armazenamento indisponível');return persistSnapshot(snapshot,target)}).then(()=>setSaveStatus(target?(hosted?'Salvo no servidor':'Salvo no banco local'):'Salvo neste navegador')).catch(err=>{lastPersistError=err;setSaveStatus('Não foi possível salvar');toast(err.message||'Não foi possível salvar. Exporte uma cópia antes de sair.');});};if(immediate)persist();else saveTimer=setTimeout(persist,180);}
function setSaveStatus(text){saveStatus=text;const el=$('#save-status');if(el)el.textContent=text;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function selected(){return state.pokemon.find(p=>p.id===state.selected)||state.pokemon[0];}
function calculated(p){return battleStats(p,bySpecies(p.speciesId),state.trainer.level,byNature(p.nature));}
function hp(p){return p.hp===null?calculated(p).values[0]:p.hp;}
function normalizeHP(){for(const p of state.pokemon){if(p.hp===null)p.hp=calculated(p).values[0];p.hp=Math.max(0,Number(p.hp)||0);}state.trainer.hp=Math.max(0,Number(state.trainer.hp)||0);}
function trainerHP(){return Math.max(1,Math.floor(state.trainer.survival[0]/hpDivisor(state.trainer.level)));}
const pendingFormArt='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240"><rect width="240" height="240" rx="24" fill="#e7f5f3"/><circle cx="120" cy="100" r="48" fill="none" stroke="#5AC5BD" stroke-width="7"/><path d="M72 100h96" stroke="#5AC5BD" stroke-width="7"/><circle cx="120" cy="100" r="14" fill="#e7f5f3" stroke="#5AC5BD" stroke-width="7"/><text x="120" y="182" text-anchor="middle" font-family="Arial" font-size="14" fill="#285C59">Imagem em revisão</text></svg>');
function photo(p){if(p.appearance==='custom'&&p.formImages?.[imageKey(p)])return p.formImages[imageKey(p)];if(p.appearance==='custom'&&!activeMega(p)&&p.formImages?.[imageKey({...p,gimmicks:{}})])return p.formImages[imageKey({...p,gimmicks:{}})];const mega=activeMega(p),g=p.gimmicks;if(mega)return g.megaCustom&&g.megaImages[mega.id]?g.megaImages[mega.id]:mega.artId?art(mega.artId,p.appearance==='shiny'):pendingFormArt;const variant=permanentVariant(p,bySpecies(p.speciesId));return p.appearance==='custom'?p.customImage:variant?(variant.artId?art(variant.artId,p.appearance==='shiny'):pendingFormArt):art(p.speciesId,p.appearance==='shiny');}
function pokeImage(p,className='',loading='lazy'){const src=photo(p);return src?`<img class="${className}" src="${escape(src)}" alt="${escape(p.nickname||bySpecies(p.speciesId).name)}${p.appearance==='shiny'?' shiny':''}" loading="${loading}" referrerpolicy="no-referrer">`:`<span class="image-fallback">${icon('image')}</span>`;}
function portrait(className){return state.trainer.portrait?`<img class="${className}" src="${escape(state.trainer.portrait)}" alt="Retrato de ${escape(state.trainer.name)}">`:`<span class="${className}">${escape(state.trainer.name.slice(0,1)||'T')}</span>`;}
function available(id){const total=state.inventory.find(i=>i.id===id)?.qty||0;return total-state.pokemon.filter(p=>p.held===id).length;}
function fullRender(){
 const labels={pokemon:'Equipe & coleção',trainer:'Meu treinador',inventory:'Inventário',journal:'Diário de jornada',catalog:'Pokédex',help:'Sobre o protótipo',account:'Conta e fichas',author:'Editor do catálogo',campaigns:'Campanhas'};
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('ball')}</div><span class="brand-word">Rotom-Phone</span></div><div class="brand-sub">Pokémon RPG</div><div class="campaign">${icon('map')}<div><small>Campanha</small><strong>${escape(campaignUI.name())}</strong></div></div><nav aria-label="Navegação principal"><div class="nav-label">Sua aventura</div>${[['trainer','person','Meu treinador'],['pokemon','ball','Pokémon'],['inventory','bag','Inventário'],['journal','book','Diário'],['campaigns','map','Campanhas']].map(([id,ic,label])=>`<button class="nav-btn ${view===id?'active':''}" data-nav="${id}" title="${label}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='pokemon'?`<span class="nav-count">${state.pokemon.length}</span>`:''}</button>`).join('')}<div class="nav-label">Referências</div>${[['catalog','grid','Pokédex'],['account','person','Conta e fichas'],...(currentAccount?.catalog_admin?[['author','edit','Editar catálogo']]:[]),['help','info','Sobre o protótipo']].map(([id,ic,label])=>`<button class="nav-btn ${view===id?'active':''}" data-nav="${id}" title="${label}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><div class="prototype-pill">${hosted?'VERSÃO DE TESTES · V1':'PRÉVIA LOCAL · V1'}</div><div class="profile">${portrait('avatar')}<div class="profile-text"><strong>${escape(state.trainer.name)}</strong><small>${escape(state.trainer.className)} · Nv. ${state.trainer.level}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Minha jornada <span>/</span><strong>${labels[view]}</strong></div><div class="top-tools"><button class="mobile-menu-button" data-action="mobile-menu">Menu</button><button data-action="toggle-theme" title="Alternar modo escuro">${icon('moon')}</button><button data-nav="campaigns">${icon('map')} Campanhas</button>${connectedSheet?'<button data-campaign-action="history">Histórico do mestre</button>':''}<button data-action="account-page">${icon('person')} ${currentAccount?escape(currentAccount.name):'Conta e fichas'}</button><span><i class="save-dot"></i><span id="save-status">${db?saveStatus:'Salvamento indisponível'}</span></span><button data-action="import" title="Importar ou trocar de ficha">${icon('upload')} Importar ficha</button><button data-action="export" title="Baixar uma cópia dos dados locais">${icon('download')} Exportar ficha</button></div></header><div class="page">${connectedSheet&&connectedSheet.ownerId!==currentAccount?.id?'<p class="panel-note">Você está editando uma ficha de jogador. Suas alterações ficam no histórico por 8 dias.</p>':''}${({pokemon:pokemonView,trainer:trainerView,inventory:inventoryView,journal:journalView,catalog:catalogView,help:helpView,account:accountView,author:authorView,campaigns:()=>campaignUI.render()})[view]()}</div></main></div>`;
}
const renderPage=fullRender;fullRender=function(){renderPage();refreshBlend();};
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1></div>${actions}</div>`;}
function pokemonView(){return `${heading('Seus parceiros de aventura','Equipe & coleção','Cada Pokémon tem uma história. Esta é a de vocês.',button('new-pokemon','Novo Pokémon','primary','plus'))}<div class="summary-strip"><div class="summary-item"><span class="summary-icon">${icon('ball')}</span><div><strong>${state.pokemon.length.toString().padStart(2,'0')}</strong><span class="meta">Pokémon na coleção</span></div></div><div class="summary-item"><span class="summary-icon">${icon('heart')}</span><div><strong>${state.pokemon.filter(p=>p.team).length} <span style="font-size:12px;color:#96a187">/ 6</span></strong><span class="meta">Companheiros na equipe</span></div></div><div class="summary-item"><span class="summary-icon">${icon('star')}</span><div><strong>${state.trainer.level}</strong><span class="meta">Nível compartilhado</span></div></div></div><div class="workspace"><section class="collection-panel" aria-label="Coleção de Pokémon"><div class="segmented"><button data-filter="all" class="${collectionFilter==='all'?'active':''}">Todos</button><button data-filter="team" class="${collectionFilter==='team'?'active':''}">Equipe</button><button data-filter="reserve" class="${collectionFilter==='reserve'?'active':''}">Reserva</button></div><div class="search">${icon('search')}<input id="pokemon-search" aria-label="Buscar Pokémon" placeholder="Buscar Pokémon ou apelido…" value="${escape(collectionQuery)}"></div><div class="collection-label"><span>Seus Pokémon</span><button class="inline-link" data-action="retired-list">Retirados (${state.retiredPokemon?.length||0})</button></div><div class="roster" id="roster">${rosterHTML()}</div></section><section class="detail" id="detail">${detailHTML()}</section></div>`;}
function filteredPokemon(){const q=collectionQuery.toLocaleLowerCase('pt-BR');return state.pokemon.filter(p=>(collectionFilter==='all'||(collectionFilter==='team'?p.team:!p.team))&&`${p.nickname} ${bySpecies(p.speciesId).name} ${permanentVariant(p,bySpecies(p.speciesId))?.name||''}`.toLocaleLowerCase('pt-BR').includes(q));}
function rosterHTML(){const list=filteredPokemon();return list.length?list.map(p=>{const s=bySpecies(p.speciesId),c=calculated(p);return `<button class="poke-card ${p.id===state.selected?'selected':''}" data-select="${p.id}" aria-label="Abrir ficha de ${escape(p.nickname||s.name)}">${pokeImage(p,'thumbnail')}<div><strong>${escape(p.nickname||s.name)}</strong><small>${escape(permanentVariant(p,s)?(p.nickname?s.name+' · ':'')+permanentVariant(p,s).name:p.nickname?s.name:s.types.join(' / '))} ${p.appearance==='shiny'?'· ✦':''}</small><div class="mini-hp"><span style="width:${Math.min(100,c.values[0]?hp(p)/c.values[0]*100:0)}%"></span></div></div><span class="card-status">${p.team?'●':'○'}</span></button>`}).join(''):'<div class="empty">Nenhum parceiro encontrado.<br>Tente outro nome ou filtro.</div>';}
function detailHTML(){const p=selected();if(!p)return '<div class="empty">Adicione seu primeiro Pokémon.</div>';const s=permanentSpecies(p,bySpecies(p.speciesId)),c=calculated(p);return `<div class="detail-header"><div><div class="dex-number">POKÉDEX Nº ${String(s.id).padStart(4,'0')} · ${p.team?'NA EQUIPE':'NA RESERVA'} · ${escape(p.gender||'Não definido')}</div><div class="detail-title"><h2><button class="inline-link" data-reference="species:${s.id}" title="Consultar espécie no Pokédex">${escape(p.nickname||s.name)}</button></h2><button data-action="edit-pokemon" aria-label="Editar nome, Nature e gênero" class="close">${icon('edit')}</button></div><div class="species-line"><span>${escape(s.name)}</span><button class="inline-link" data-action="change-species">Alterar espécie</button></div><label class="variant-picker">Variante<select id="permanent-variant"><option value="">Padrão</option>${variantsFor(bySpecies(p.speciesId)).map(v=>`<option value="${v.id}" ${p.variantId===v.id?'selected':''}>${escape(v.name)}</option>`).join('')}</select>${variantsFor(bySpecies(p.speciesId)).length?'':'<small>Sem variantes cadastradas na amostra</small>'}</label><div class="subline">${battleTypes(p,s).defense.map(type).join('')}<span>Nível ${state.trainer.level}</span></div></div><span class="rank-badge" title="BST + PE: ${c.total}">${rankContent(c)}</span></div><div class="detail-tabs" role="tablist" aria-label="Seções da ficha">${[['overview','Visão geral'],['training','Atributos & treino'],['moves','Movimentos'],['appearance','Aparência'],['notes','Contest & notas']].map(([id,label])=>`<button role="tab" aria-selected="${detailTab===id}" class="${detailTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div class="detail-body">${({overview:overview,training:trainingTab,moves:movesTab,appearance:appearanceTab,notes:notesTab,ability:abilityTab})[detailTab](p,s,c)}</div>`;}
function overview(p,s,c){const current=hp(p),max=Math.max(1,c.values[0]),nature=byNature(p.nature),held=byItem(p.held);return `<div class="overview-top"><div><div class="pokemon-art">${gimmickBadges(p)}${pokeImage(p,'','eager')}<button class="art-edit" data-tab="appearance" aria-label="Personalizar aparência">${icon('image')}</button></div><div class="nature-line"><button class="inline-link" data-action="edit-pokemon">Natureza · alterar</button><strong>${nature.pt} <span style="color:#a0aa92">/ ${nature.id}</span></strong></div></div><div><div class="health-head"><span class="label">Pontos de vida</span><strong class="hp-value">${current}<small> / ${max}</small></strong></div><div class="progress-bar ${current<max*.3?'low':''}"><span style="width:${Math.min(100,max?current/max*100:0)}%"></span></div><div class="health-actions"><div><button class="step-btn" data-hp="-1" aria-label="Perder 1 HP">−</button> <button class="step-btn" data-hp="1" aria-label="Recuperar 1 HP">+</button> <button class="text-btn" data-action="edit-hp">Ajustar</button></div></div><fieldset class="conditions"><legend>Condições ativas</legend>${['Queimadura','Congelamento','Sono','Paralisia','Veneno','Veneno pesado','Paixão','Confusão'].map(v=>`<label><input type="checkbox" data-condition="${v}" ${p.conditions.includes(v)?'checked':''}>${v}</label>`).join('')}</fieldset><div class="trust-box"><div class="trust-head"><span>${icon('heart')} Confiança</span><strong>${p.confidence} <span style="color:#a0ab93;font-weight:400">/ 255</span></strong></div><div class="progress-bar trust-progress"><span style="width:${p.confidence/255*100}%"></span></div><div class="trust-caption"><span>${trust(p.confidence)}</span><button data-action="edit-trust" title="Ajustar confiança">${icon('edit')}</button></div></div></div></div>${pokemonAbilityUI(p)}${heldBox(p,held)}${combatStatsHTML(p,s,c)}${accuracyControls(p)}<div class="section-line"><h3>Movimentos ativos</h3><small>${p.active.length} / ${activeLimit(state.trainer.level)} espaços</small></div>${p.active.length?p.active.map(id=>moveRow(byMove(id),s,p)).join(''):'<div class="empty">Este Pokémon ainda não tem golpes ativos.<br>Adicione-os na aba Movimentos.</div>'}<p class="micro-note">Dano exibido = base do movimento. Some o atributo ofensivo e os bônus aplicáveis. Estágios já estão aplicados aos atributos acima e à DT. Itens e condições ainda são resolvidos manualmente.</p>${gimmickPanel(p,s)}<div class="footer-action">${button('retire-pokemon','Retirar da coleção','secondary small')}${button('toggle-team',p.team?'Mover para reserva':'Adicionar à equipe','light small',p.team?'moon':'plus')}</div>`;}
function moveRow(base,s,p){if(!base)return '';const m=effectiveMove(p,base,moves),types=battleTypes(p,s),stab=m.power&&types.stab.includes(m.type);return `<div class="move-slot"><div class="move-row"><div class="move-name">${moveCategoryIcon(m.cat)}<div><strong><button class="inline-link" data-move-info="${base.id}">${escape(m.pt)}</button>${stab?`<span class="stab">STAB +${types.stabDice}d4</span>`:''}</strong><small>${escape(m.name)} · ${escape(m.cat)}</small></div></div>${type(m.type)}<div class="move-number">${m.pending?'—':damage(m.power)}<small>${m.pending?'Em desenvolvimento':'Dano base'}</small></div><div class="move-number">${combatDT(m.acc,p.stages[5])}<small>DT atual</small></div></div><div class="temporary-move-controls">${m.temporary?`<span>Habitual: ${escape(base.pt)}</span>`:'<span></span>'}<div><button class="text-btn" data-temp-move="${base.id}">Trocar temporariamente</button>${p.temporaryMoves?.[base.id]?`<button class="text-btn" data-restore-move="${base.id}">Remover troca</button>`:''}</div></div></div>`;}
function trainingTab(p,s,c){return `<div class="panel-note">Rank <strong>${c.rank}</strong> · ${s.base.reduce((a,b)=>a+b,0)} BST + ${c.pe.reduce((a,b)=>a+b,0)} PE = <strong>${c.total}</strong>. Natureza e bônus temporários não alteram o Rank.</div><h3>Atributos permanentes</h3><p class="input-note">Todos os Pontos de Esforço ficam no mesmo total, independentemente da origem.</p><table class="editable-table"><thead><tr><th>Atributo</th><th>Base</th><th>PE</th><th>Treino</th></tr></thead><tbody>${STAT_LABELS.map((label,i)=>`<tr><td>${i===5?'Speed':label}</td><td>${s.base[i]}</td><td><input type="number" min="-9999" max="9999" value="${p.pe[i]}" data-pe="${i}" aria-label="PE ${label}"></td><td><div class="train-controls">${p.progress[i]}/3 <button class="step-btn" data-train="${i}" aria-label="Treinar ${label}">+</button></div></td></tr>`).join('')}</tbody></table><p class="micro-note">Cada 3 pontos de Condicionamento acrescentam +10 PE ao total do atributo.</p>`;}
function movesTab(p,s){return `<div class="active-moves-preview"><h3>Movimentos em uso</h3>${p.active.map(id=>moveRow(byMove(id),s,p)).join('')}</div><div class="moves-toolbar"><div><h3>Memória de movimentos</h3><p class="input-note">${p.active.length} ativos · ${p.known.length} conhecidos</p></div>${button('learn-move','Registrar golpe','light small','plus')}</div><div class="panel-note">Desativar um movimento preserva seu aprendizado. Reorganize os ativos em um local seguro, conforme a V1.</div>${p.known.length?p.known.map(id=>{const m=byMove(id);return `<div class="move-memory"><div class="move-text"><h3><button class="inline-link" data-reference="moves:${m.id}">${escape(m.pt)}</button></h3><small>${escape(m.name)} · ${m.cat} · ${damage(m.power)} base · DT ${combatDT(m.acc,p.stages[5])}</small><p>${escape(m.effect)}</p><div style="margin-top:9px">${type(m.type)}</div></div><button class="btn ${p.active.includes(id)?'light':'secondary'} small" data-move-toggle="${id}">${p.active.includes(id)?'✓ Ativo':'Ativar'}</button><button class="btn secondary small" data-forget-move="${escape(id)}">Apagar</button></div>`}).join(''):'<div class="empty">Registre o primeiro movimento deste parceiro.</div>'}<p class="readme-warning">Pokédex demonstrativo: compatibilidade, origem do aprendizado e learnsets ainda não são validados. Traduções são propostas de interface, abertas à sua revisão.</p>`;}
function appearanceTab(p){return `<h3>Aparência</h3>${formImageGallery(p)}<p class="input-note">A aparência é independente dos atributos e da espécie.</p><div class="appearance-grid">${[['normal','Normal'],['shiny','Shiny'],['custom','Personalizada']].map(([id,label])=>`<button class="appearance-option ${p.appearance===id?'active':''}" data-appearance="${id}" aria-pressed="${p.appearance===id}">${id==='custom'?(p.customImage?`<img src="${escape(p.customImage)}" alt="Imagem personalizada">`:icon('image')):`<img src="${art(permanentVariant(p,bySpecies(p.speciesId))?.artId||p.speciesId,id==='shiny')}" alt="${label}">`}<strong>${label}</strong></button>`).join('')}</div><div class="upload-zone">${icon('upload')}<h3 style="margin-top:10px">Imagem personalizada</h3><p>Envie uma imagem para este Pokémon ou vincule uma arte à combinação atual de forma e gimmicks.</p><label class="btn light upload-label">Imagem desta forma<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" data-upload="form"></label>${p.formImages?.[imageKey(p)]?button('remove-form-image','Remover imagem desta forma','secondary small'):''}<label class="btn primary upload-label">${icon('upload')} Escolher imagem<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" data-upload="pokemon"></label><p style="margin-bottom:0;font-size:10px">PNG, JPG ou WebP · até 8 MB<br>A imagem é otimizada e guardada junto à ficha.</p></div><div class="fields"><label class="field full">Ou usar um link de imagem personalizada<input id="custom-url" type="url" placeholder="https://…" value="${p.customImage.startsWith('https://')?escape(p.customImage):''}"></label></div><div class="footer-action">${p.customImage?button('remove-image','Remover personalizada','secondary small'):''}${button('custom-url','Usar link geral','light small')}${button('form-url','Vincular link à forma atual','secondary small')}</div><p class="micro-note">Trocar para Normal ou Shiny preserva a imagem personalizada. Só o botão “Remover” apaga essa referência.</p>`;}
function notesTab(p){return `<h3>Atributos de Contest</h3><div class="segmented sub-tabs"><button data-contest-tab="values" class="${contestTab==='values'?'active':''}">Atributos</button><button data-contest-tab="training" class="${contestTab==='training'?'active':''}">Treino de Contest</button></div><p class="input-note">Começam em zero. Distribua os pontos de captura conforme a mesa. Cada 3 pontos de treino aumentam o atributo em 1, até 10.</p><div class="compact-grid" style="margin-top:18px">${['Carisma','Beleza','Fofura','Esperteza','Vigor'].map((v,i)=>`<div class="counter-card"><label for="contest-${i}">${v}</label><input id="contest-${i}" type="number" min="0" max="10" data-contest="${i}" value="${p.contest[i]}">${contestTab==='training'?`<div class="train-controls"><span>${p.contestProgress[i]}/3</span><button class="step-btn" data-contest-delta="${i}" data-delta="1" aria-label="Treinar ${v}">+</button></div>`:''}</div>`).join('')}<div class="counter-card"><label for="talent">Talento atual</label><input id="talent" type="number" min="0" max="999" data-pfield="talent" value="${p.talent}"></div></div><div class="fields"><label class="field full">${contestTab==='training'?'Registro de treinos de Contest':'Personalidade, vínculos e conquistas'}<textarea data-pfield="${contestTab==='training'?'contestNotes':'notes'}">${escape(contestTab==='training'?p.contestNotes:p.notes)}</textarea></label></div>`;}
function trainerView(){const t=state.trainer;return `${heading('Quem escreve esta história','Meu treinador','Mais do que uma classe. Uma história em construção.')}<div class="grid-two"><div class="card"><div class="trainer-top">${portrait('portrait-big')}<div class="trainer-identity"><h2>${escape(t.name)}</h2><p class="subtitle">${escape(t.className)} · Nível ${t.level}</p><label class="btn light small upload-label" style="margin-top:10px">${icon('image')} Alterar retrato<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" data-upload="trainer"></label></div>${trainerRank(t.prestige)}</div>${trainerCombat(t)}<div class="fields">${trainerInput('name','Nome do personagem')}${trainerInput('player','Jogador')}<label class="field full">Classe principal<textarea data-tfield="className" maxlength="160" style="min-height:72px" placeholder="Inclua sua especialidade ou um nome próprio">${escape(t.className)}</textarea></label>${trainerInput('profession','Profissão')}${trainerInput('level','Nível compartilhado','number',1,100)}${trainerInput('prestige','Pontos de Prestígio','number',0,99999)}${trainerInput('aura','Pontos de Aura','number',0,2)}</div><p class="input-note">Prestígio: <strong>${rank(t.prestige)}</strong>. Bônus de classe e marcos de nível ainda são distribuídos manualmente.</p><div class="section-line"><h3>Atributos pessoais</h3><small>Dados do treinador</small></div><div class="fields" style="grid-template-columns:repeat(3,1fr)">${['Corpo','Mente','Espírito'].map((v,i)=>`<label class="field">${v}<select data-attribute="${i}">${['Sem dado','1d2','1d4','1d6','1d8','1d10','1d12'].map((v,j)=>`<option value="${j}" ${t.attributes[i]===j?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><div class="section-line"><h3>Sobrevivência</h3><small>HP ${t.hp} / ${trainerHP()}</small></div><div class="fields">${['HP','Defesa','Def. especial','Speed'].map((v,i)=>`<label class="field">${v} · PE<input type="number" min="-9999" max="9999" data-survival="${i}" value="${t.survival[i]}"></label>`).join('')}<label class="field">HP atual<input type="number" min="0" data-tfield="hp" value="${t.hp}"></label></div><p class="input-note">DEF ${Math.floor(t.survival[1]/10)} · Sp. DEF ${Math.floor(t.survival[2]/10)} · Evasão ${Math.floor(t.survival[3]/20)}. Distribuição de PE livre, incluindo ajustes negativos.</p></div><div class="card"><h2>Perícias</h2>${attributeDice(t)}<p class="subtitle">O atributo depende da abordagem. Maestria concede vantagem.</p><div class="skills-grid">${t.skills.map((s,i)=>({...s,index:i})).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map((s)=>`<div class="skill"><span>${escape(s.name)}</span><input type="number" min="-9999" max="9999" value="${s.bonus}" data-skill="${s.index}" aria-label="Bônus de ${escape(s.name)}"><label title="Maestria"><input type="checkbox" data-mastery="${s.index}" ${s.mastery?'checked':''}> M</label></div>`).join('')}</div><p class="micro-note">Bônus e Maestria editáveis para testar a ficha. Proficiências e progressos de Aprendizado terão registros próprios.</p></div></div><div class="card" style="margin-top:22px"><h2>História, objetivos & vínculos</h2><div class="fields"><label class="field full">História<textarea data-tfield="story">${escape(t.story)}</textarea></label><label class="field">Objetivos<textarea data-tfield="goals">${escape(t.goals)}</textarea></label><label class="field">Vínculos<textarea data-tfield="bonds">${escape(t.bonds)}</textarea></label></div></div>${trainerAbilities(t)}`;}
function trainerInput(key,label,type='text',min=0,max=999){return `<label class="field">${label}<input data-tfield="${key}" type="${type}" value="${escape(state.trainer[key])}" ${type==='number'?`min="${min}" max="${max}"`:'maxlength="100"'}></label>`;}
function inventoryView(){return `${heading('Tudo o que vai com você','Inventário','Preparado para o próximo encontro.',button(inventoryTab==='cultivation'?'new-cultivation':'add-item',inventoryTab==='cultivation'?'Novo plantio':'Adicionar item','primary','plus'))}<div class="summary-strip"><div class="summary-item"><span class="summary-icon">${icon('bag')}</span><div><strong>${state.inventory.length}</strong><span class="meta">Tipos de item</span></div></div><div class="summary-item"><div><strong>P$ ${state.trainer.money.toLocaleString('pt-BR')}</strong><span class="meta">Pokédólares</span></div><button class="close" data-action="money" aria-label="Editar dinheiro">${icon('edit')}</button></div></div><div class="segmented sub-tabs">${[['items','Itens'],['blocks','Pokéblocks'],['cultivation','Estufa portátil']].map(([id,label])=>`<button data-inventory-tab="${id}" class="${inventoryTab===id?'active':''}">${label}</button>`).join('')}</div>${inventoryTab==='cultivation'?cultivationView():inventoryTab==='blocks'?pokeblocksView():`<div class="inventory-toolbar">${orderingSelect('inventory-order',inventoryOrder,true)}<div class="search">${icon('search')}<input id="inventory-search" aria-label="Buscar item" placeholder="Buscar item…" value="${escape(inventoryQuery)}"></div><select class="control" id="inventory-category" aria-label="Categoria de item"><option value="all">Todas as categorias</option>${[...new Set(allItems().map(i=>i.category))].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(c=>`<option ${c===inventoryCategory?'selected':''}>${c}</option>`).join('')}</select></div><div class="inventory-grid" id="inventory-grid">${inventoryCards()}</div>`}<p class="micro-note">Os itens equipados reservam uma unidade do estoque. Descrições e imagens usam a mesma referência do Pokédex.</p>`;}
function inventoryCards(){const q=inventoryQuery.toLowerCase();const filtered=state.inventory.filter(e=>{const i=byItem(e.id);return i&&(inventoryTab==='blocks'?i.category==='Pokéblocks':i.category!=='Pokéblocks')&&(inventoryCategory==='all'||i.category===inventoryCategory)&&`${i.name} ${i.pt} ${i.effect}`.toLowerCase().includes(q)});const ordered=orderReferences(filtered.map(e=>({...byItem(e.id),entry:e})),'items',inventoryOrder).map(i=>i.entry);return ordered.length?ordered.map(e=>{const i=byItem(e.id);return `<article class="item-card"><button class="item-card-head reference-card" data-reference="items:${i.id}"><div class="item-image">${itemImage(i)?`<img src="${escape(itemImage(i))}" alt="${escape(i.pt)}" loading="lazy">`:icon('bag')}</div><div><h3>${escape(i.pt)}</h3><small>${escape(i.category)}</small></div></button><p>${escape(i.effect)}</p><div class="item-card-foot"><span>${available(i.id)} disponíveis</span><div class="quantity"><button class="step-btn" data-qty="${i.id}" data-delta="-1" aria-label="Remover uma unidade de ${escape(i.pt)}">−</button><button class="inline-link" data-item-quantity="${escape(i.id)}" title="Ajustar quantidade">${e.qty} · editar</button><button class="step-btn" data-qty="${i.id}" data-delta="1" aria-label="Adicionar uma unidade de ${escape(i.pt)}">+</button></div></div></article>`}).join(''):'<div class="empty">Nenhum item aqui ainda. Adicione itens do Pokédex ou crie um personalizado.</div>';}
function journalView(){return `${heading('As histórias entre as batalhas','Diário de jornada','Suas descobertas, organizadas em notas.',button('new-note','Nova nota','primary','plus'))}<div class="search note-search">${icon('search')}<input id="note-search" aria-label="Buscar nas notas" placeholder="Buscar no título ou no texto…" value="${escape(noteQuery)}"></div><div class="grid-two"><section class="card"><h2>Suas notas</h2><div id="note-list">${noteList()}</div></section><section class="card"><h2>${noteDraft.id?'Editar nota':'Escrever uma nota'}</h2><form id="note-form"><div class="fields"><label class="field full">Título<input name="title" id="note-title" maxlength="120" value="${escape(noteDraft.title)}" placeholder="Ex.: O mistério da ilha rosa" required></label><label class="field full">Texto<textarea class="notebook" name="text" id="note-text" required>${escape(noteDraft.text)}</textarea></label></div><button class="btn primary" type="submit">Salvar nota</button><p class="input-note">Salve para criar ou atualizar esta página do caderno.</p></form></section></div>`;}
function catalogView(){return `${heading('Conhecimento para a jornada','Pokédex','Referências compartilhadas pelas fichas e pelo inventário.')}<div class="segmented sub-tabs">${[['species','Pokémon'],['variants','Formas'],['megaForms','Megas'],['moves','Movimentos'],['abilities','Habilidades'],['items','Itens']].map(([id,label])=>`<button data-catalog-tab="${id}" class="${catalogTab===id?'active':''}">${label}</button>`).join('')}</div><div class="search note-search">${icon('search')}<input id="catalog-search" aria-label="Buscar no Pokédex" placeholder="Buscar por nome, tipo ou descrição…" value="${escape(catalogQuery)}"></div>${catalogOrderUI()}<div class="panel-note">${catalogRecords(catalogTab).length} referências no catálogo central. Traduções e adaptações ainda não revisadas aparecem como em desenvolvimento.</div><div class="catalog-list" id="catalog-results">${catalogResults()}</div>`;}
function helpView(){return `${heading('Uma primeira versão para experimentar','Sobre o protótipo','Vamos descobrir juntos o que funciona em mesa.')}<div class="grid-two"><div class="card"><h2>Já dá para testar</h2><ul class="help-list"><li><strong>Coleção sem grade fixa</strong><br>Crie indivíduos, busque parceiros e escolha até seis para a equipe. A reserva não tem limite de espaços definido pelo aplicativo.</li><li><strong>Aparência livre</strong><br>Normal, shiny e imagem personalizada por upload ou link. Retrato do treinador também é editável.</li><li><strong>Valores da V1</strong><br>Rank por BST + PE, HP por nível compartilhado, Defesa por divisão por 10, Nature, Confiança e Condicionamento.</li><li><strong>Seu material de jogo</strong><br>Movimentos ativos/conhecidos, inventário com imagens, held item, atributos de Contest e diário.</li></ul></div><div class="card"><h2>O que esta prévia não faz</h2><ul class="help-list"><li><strong>Não é sua ficha real</strong><br>Os dados são demonstrativos, inspirados na ficha do Sherma. Nada foi alterado no Google Drive.</li><li><strong>Salvamento local</strong><br>O rascunho fica neste navegador. Em Conta e fichas, você pode criar uma conta local e guardar personagens no banco deste PC. Exporte cópias para preservar seus dados.</li><li><strong>Automação parcial</strong><br>Estágios ajustam atributos e DT. Itens, condições, classes e gimmicks ainda não aplicam seus efeitos. O dano mostrado nos golpes é só o dano base.</li><li><strong>Próxima etapa</strong><br>Revisar o design com você antes de integrar o Pokédex completo, o banco e as campanhas.</li></ul>${button('export','Exportar dados de teste','primary','download')}</div></div>`;}
function renderDetail(){if($('#detail'))$('#detail').innerHTML=detailHTML();if($('#roster'))$('#roster').innerHTML=rosterHTML();}
function modal(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close-dialog" aria-label="Fechar">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;dialog.showModal();}
function modalActions(label='Salvar'){return `<p class="form-error" id="form-error" role="alert"></p><div class="dialog-actions">${button('close-dialog','Cancelar','secondary')}<button type="submit" class="btn primary">${label}</button></div>`;}
function newPokemonDialog(){modal('Novo Pokémon',`<form id="new-pokemon-form"><p class="input-note" style="margin-top:0">Cada Pokémon ganha sua própria ficha, mesmo que você já tenha outro da mesma espécie.</p><div class="fields"><div class="field full" id="new-species-picker"></div><label class="field full">Apelido <span style="display:inline;color:#9ca88e">opcional</span><input name="nickname" maxlength="60" placeholder="Como você vai chamá-lo?"></label><label class="field">Confiança inicial<input type="number" name="confidence" min="0" max="255" value="50" required></label>${genderField()}<label class="field">Natureza<select name="nature">${natures.map(n=>`<option value="${n.id}">${n.pt} / ${n.id}</option>`).join('')}</select></label></div><div id="new-preview"></div><p class="input-note">O parceiro entra na reserva. Depois você pode colocá-lo na equipe, registrar golpes e enviar uma imagem personalizada.</p>${modalActions('Criar ficha')}</form>`);mountSpeciesPicker($('#new-species-picker'),{catalog:species,onSelect:s=>{$('#new-preview').innerHTML=s?speciesPreview(s):'';}});}
function speciesPreview(s){return `<div class="preview-species"><img src="${art(s.id)}" alt="${escape(s.name)}"><div><h3>${escape(s.name)}</h3><div style="margin-top:9px">${s.types.map(type).join(' ')}</div><small>BST ${s.base.reduce((a,b)=>a+b,0)} · ${rank(s.base.reduce((a,b)=>a+b,0))}</small></div></div>`;}
function editPokemonDialog(){const p=selected();modal('Identidade do parceiro',`<form id="edit-pokemon-form"><div class="fields" style="margin-top:0"><label class="field full">Apelido<input name="nickname" value="${escape(p.nickname)}" maxlength="60" placeholder="${bySpecies(p.speciesId).name}"></label>${genderField(p.gender)}<label class="field full">Natureza<select name="nature">${natures.map(n=>`<option value="${n.id}" ${n.id===p.nature?'selected':''}>${n.pt} / ${n.id}</option>`).join('')}</select></label></div><p class="input-note">Nature afeta valores derivados, sem alterar Base Stats ou Rank.</p>${modalActions()}</form>`);}
function numberDialog(kind,title,value,max){modal(title,`<form id="number-form" data-kind="${kind}"><label class="field">${title}<input name="value" type="number" min="0" max="${max}" value="${value}" required autofocus></label>${modalActions()}</form>`);}
function heldDialog(){const p=selected();modal('Item equipado',`<form id="held-form"><p class="input-note" style="margin-top:0">Escolha uma unidade disponível no inventário. Remover o item devolve a unidade à disponibilidade.</p><div class="fields"><label class="field full">Held item<select name="item"><option value="">Nenhum item</option>${state.inventory.filter(e=>['Equipáveis','Berries','Personalizados'].includes(byItem(e.id).category)).map(e=>{const i=byItem(e.id);return `<option value="${e.id}" ${p.held===e.id?'selected':''} ${available(e.id)<=0&&p.held!==e.id?'disabled':''}>${escape(i.pt)} · ${available(e.id)+(p.held===e.id?1:0)} disponível(is) para este Pokémon</option>`}).join('')}</select></label></div>${modalActions('Equipar')}</form>`);}
function learnDialog(){const options=moves.filter(m=>!selected().known.includes(m.id));modal('Registrar movimento',`<form id="learn-form"><div id="move-picker"></div>${modalActions('Adicionar à memória')}</form>`);mountReferencePicker($('#move-picker'),{records:options,name:'move',label:'movimento'});}
function addItemDialog(){customItemImage='';modal('Adicionar ao inventário',`${button('custom-item','Criar item personalizado','light','plus')}<form id="add-item-form"><div id="item-picker"></div><label class="field">Quantidade<input type="number" min="1" max="9999" name="qty" value="1" required></label>${modalActions('Adicionar item')}</form>`);mountReferencePicker($('#item-picker'),{records:allItems(),name:'item',label:'item'});}
async function handleUpload(input){const file=input.files?.[0];if(!file)return;const owner=input.dataset.upload==='form'?'form:'+selected().id+'|'+imageKey(selected()):input.dataset.upload==='mega'?'mega:'+input.dataset.pokemonId+':'+input.dataset.megaId:input.dataset.upload==='item'?'item':input.dataset.upload==='trainer'?'trainer':selected().id;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Escolha um arquivo PNG, JPG ou WebP.');input.value='';return;}if(file.size>8*1024*1024){toast('Escolha uma imagem com até 8 MB.');input.value='';return;}const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();if(im.width*im.height>40000000)throw Error('Imagem muito grande');const scale=Math.min(1,768/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.86);if(owner.startsWith('form:')){const [pid,key]=owner.slice(5).split('|'),p=state.pokemon.find(p=>p.id===pid);if(!p)throw Error();p.formImages ||= {};p.formImages[key]=data;p.appearance='custom';save(true);fullRender();toast('Imagem vinculada à forma atual.');return;}if(owner.startsWith('mega:')){const [,pid,mid]=owner.split(':'),p=state.pokemon.find(p=>p.id===pid);if(!p)throw Error();gimmicks(p).megaImages[mid]=data;gimmicks(p).megaCustom=true;save(true);fullRender();toast('Arte da Mega salva; a imagem habitual foi preservada.');return;}if(owner==='item'){customItemImage=data;$('#custom-item-preview').innerHTML=`<img src="${data}" alt="Imagem do item personalizado">`;toast('Imagem pronta para o item.');return;}if(owner==='trainer')state.trainer.portrait=data;else{const p=state.pokemon.find(p=>p.id===owner);p.customImage=data;p.appearance='custom';}save();fullRender();toast('Imagem personalizada salva localmente.');}catch{toast('Não foi possível ler essa imagem. Tente um arquivo menor.');}finally{URL.revokeObjectURL(url);}}
function exportData(){const blob=new Blob([JSON.stringify(exportSheet(state),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rotom-phone-'+(state.trainer.name.replace(/[^a-z0-9_-]/gi,'-')||'ficha')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Cópia exportada, incluindo suas imagens personalizadas.');}
document.addEventListener('click',e=>{
 const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.nav){if(dialog.open)dialog.close();view=btn.dataset.nav;fullRender();window.scrollTo({top:0});return;}
 if(btn.dataset.select){state.selected=btn.dataset.select;save();renderDetail();return;}
 if(btn.dataset.tab){detailTab=btn.dataset.tab;renderDetail();return;}
 if(btn.dataset.filter){collectionFilter=btn.dataset.filter;fullRender();return;}
 if(btn.dataset.hp){const p=selected();p.hp=healthValue(hp(p)+Number(btn.dataset.hp));save();renderDetail();return;}
 if(btn.dataset.train!==undefined){const gained=train(selected(),Number(btn.dataset.train));normalizeHP();save();renderDetail();toast(gained?'+10 PE! O contador foi reiniciado.':'Progresso de Condicionamento registrado.');return;}
 if(btn.dataset.moveToggle){const p=selected(),id=btn.dataset.moveToggle;if(p.active.includes(id))p.active=p.active.filter(v=>v!==id);else if(p.active.length<activeLimit(state.trainer.level))p.active.push(id);else {toast('Desative um movimento antes de ativar outro.');return;}save();renderDetail();return;}
 if(btn.dataset.appearance){selected().appearance=btn.dataset.appearance;save();renderDetail();return;}
 if(btn.dataset.qty){const entry=state.inventory.find(i=>i.id===btn.dataset.qty),delta=Number(btn.dataset.delta);if(delta<0&&available(entry.id)<=0){toast('As unidades restantes estão equipadas. Remova o held item primeiro.');return;}entry.qty=clamp(entry.qty+delta,0,9999);save();$('#inventory-grid').innerHTML=inventoryCards();return;}
 switch(btn.dataset.action){
  case 'new-pokemon':newPokemonDialog();break;
  case 'edit-pokemon':editPokemonDialog();break;
  case 'edit-hp':healthDialog('pokemon');break;
  case 'trainer-hp':healthDialog('trainer');break;
  case 'edit-trust':numberDialog('confidence','Confiança',selected().confidence,255);break;
  case 'money':numberDialog('money','Pokédólares',state.trainer.money,99999999);break;
  case 'held-item':heldDialog();break;
  case 'learn-move':learnDialog();break;
  case 'add-item':addItemDialog();break;
  case 'export':exportData();break;
  case 'import':transferDialog();break;
  case 'confirm-import':confirmImport();break;
  case 'close-dialog':dialog.close();break;
  case 'toggle-team':{const p=selected();if(!p.team&&state.pokemon.filter(p=>p.team).length>=6){toast('A equipe está completa. Mova um parceiro para a reserva.');break;}p.team=!p.team;save();fullRender();toast(p.team?'Parceiro adicionado à equipe.':'Parceiro movido para a reserva.');break;}
  case 'remove-form-image':delete selected().formImages[imageKey(selected())];save();renderDetail();break;
  case 'remove-image':selected().customImage='';selected().appearance='normal';save();renderDetail();toast('Imagem personalizada removida deste Pokémon.');break;
  case 'form-url':{try{const url=new URL($('#custom-url').value.trim());if(url.protocol!=='https:')throw Error();const p=selected();p.formImages ||= {};p.formImages[imageKey(p)]=url.href;p.appearance='custom';save();renderDetail();toast('Link vinculado à forma atual.');}catch{toast('Informe um endereço de imagem que comece com https://.');}break;}
  case 'custom-url':{const value=$('#custom-url').value.trim();try{const url=new URL(value);if(url.protocol!=='https:')throw Error();selected().customImage=url.href;selected().appearance='custom';save();renderDetail();toast('Link associado a este Pokémon.');}catch{toast('Informe um endereço de imagem que comece com https://.');}break;}
 }
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='pokemon-search'){collectionQuery=el.value;$('#roster').innerHTML=rosterHTML();}if(el.id==='inventory-search'){inventoryQuery=el.value;$('#inventory-grid').innerHTML=inventoryCards();}if(el.id==='note-title')noteDraft.title=el.value;if(el.id==='note-text')noteDraft.text=el.value;if(el.id==='note-search'){noteQuery=el.value;$('#note-list').innerHTML=noteList();}if(el.id==='catalog-search'){catalogQuery=el.value;$('#catalog-results').innerHTML=catalogResults();}if(el.matches('textarea[data-pfield]')){selected()[el.dataset.pfield]=el.value;save();}if(el.matches('textarea[data-tfield]')){state.trainer[el.dataset.tfield]=el.value;save();}
 if(el.dataset.pe!==undefined){const p=selected(),index=Number(el.dataset.pe);p.pe[index]=Math.floor(clamp(el.value,-9999,9999));normalizeHP();save();const c=calculated(p),badge=$('.rank-badge');if(badge){badge.innerHTML=rankContent(c);badge.title='BST + PE: '+c.total;}const note=$('#detail .panel-note');if(note)note.innerHTML=`Rank <strong>${c.rank}</strong> · ${bySpecies(p.speciesId).base.reduce((a,b)=>a+b,0)} BST + ${c.pe.reduce((a,b)=>a+b,0)} PE = <strong>${c.total}</strong>. Natureza e bônus temporários não alteram o Rank.`;}
});
document.addEventListener('change',e=>{
 const el=e.target;if(el.id==='import-file'){readImportFile(el.files?.[0]);return;}if(el.dataset.upload){handleUpload(el);return;}if(el.id==='new-species'){$('#new-preview').innerHTML=speciesPreview(bySpecies(el.value));return;}if(el.id==='inventory-category'){inventoryCategory=el.value;$('#inventory-grid').innerHTML=inventoryCards();return;}
 let rerender=true,changed=true;
 if(el.dataset.pe!==undefined)selected().pe[Number(el.dataset.pe)]=Math.floor(clamp(el.value,-9999,9999));
 else if(el.dataset.stage!==undefined)selected().stages[Number(el.dataset.stage)]=Math.floor(clamp(el.value,-6,6));
 else if(el.dataset.contest!==undefined)selected().contest[Number(el.dataset.contest)]=Math.floor(clamp(el.value,0,10));
 else if(el.dataset.pfield){const key=el.dataset.pfield;selected()[key]=key==='talent'?Math.floor(clamp(el.value,0,999)):el.value;rerender=el.tagName!=='TEXTAREA';}
 else if(el.dataset.tfield){const key=el.dataset.tfield;const ranges={level:[1,100],prestige:[0,99999],aura:[0,2],hp:[0,Number.MAX_SAFE_INTEGER]};state.trainer[key]=ranges[key]?Math.floor(clamp(el.value,...ranges[key])):el.value;rerender=el.tagName!=='TEXTAREA';if(key==='level'){const limit=activeLimit(state.trainer.level);let removed=false;state.pokemon.forEach(p=>{if(p.active.length>limit){p.active=p.active.slice(0,limit);removed=true;}});if(removed)toast('O quinto golpe saiu dos ativos e permanece na memória.');}}
 else if(el.dataset.attribute!==undefined)state.trainer.attributes[Number(el.dataset.attribute)]=Number(el.value);
 else if(el.dataset.survival!==undefined)state.trainer.survival[Number(el.dataset.survival)]=Math.floor(clamp(el.value,-9999,9999));
 else if(el.dataset.skill!==undefined){state.trainer.skills[Number(el.dataset.skill)].bonus=Math.floor(clamp(el.value,-9999,9999));rerender=false;el.value=state.trainer.skills[Number(el.dataset.skill)].bonus;}
 else if(el.dataset.mastery!==undefined){state.trainer.skills[Number(el.dataset.mastery)].mastery=el.checked;rerender=false;}
 else changed=false;
 if(changed){normalizeHP();save();if(rerender)fullRender();}
});
document.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target,values=new FormData(form);
 if(form.id==='new-pokemon-form'){if(!species.some(s=>s.id===Number(values.get('speciesId'))))return;const p=makePokemon(Number(values.get('speciesId')),String(values.get('nickname')).trim());p.nature=String(values.get('nature'));p.gender=String(values.get('gender')||'Não definido');p.confidence=Math.floor(clamp(values.get('confidence'),0,255));state.pokemon.push(p);state.selected=p.id;collectionFilter='all';collectionQuery='';detailTab='overview';toast('Nova ficha criada. Seu parceiro está na reserva.');}
 else if(form.id==='edit-pokemon-form'){selected().nickname=String(values.get('nickname')).trim();selected().nature=String(values.get('nature'));selected().gender=String(values.get('gender'));}
 else if(form.id==='number-form'){const key=form.dataset.kind;if(key==='money')state.trainer.money=Math.floor(clamp(values.get('value'),0,99999999));else selected()[key]=Math.floor(clamp(values.get('value'),0,key==='confidence'?255:Number.MAX_SAFE_INTEGER));}
 else if(form.id==='held-form'){const id=String(values.get('item'));if(id&&selected().held!==id&&available(id)<=0){$('#form-error').textContent='Não há unidade disponível desse item.';return;}selected().held=id;}
 else if(form.id==='learn-form'){const id=String(values.get('move'));if(!byMove(id))return;if(!selected().known.includes(id))selected().known.push(id);if(selected().active.length<activeLimit(state.trainer.level))selected().active.push(id);}
 else if(form.id==='add-item-form'){const id=String(values.get('item'));if(!byItem(id))return;const qty=Math.floor(clamp(values.get('qty'),1,9999)),entry=state.inventory.find(i=>i.id===id);if(entry)entry.qty=Math.min(9999,entry.qty+qty);else state.inventory.push({id,qty});}
 else return;
 normalizeHP();save();dialog.close();fullRender();
});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const img=e.target,placeholder=document.createElement('span');placeholder.className=`image-fallback ${img.className}`;placeholder.title='Imagem indisponível';placeholder.setAttribute('role','img');placeholder.setAttribute('aria-label',img.alt+' — imagem indisponível');placeholder.innerHTML=icon('image');img.replaceWith(placeholder);}},true);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&db){clearTimeout(saveTimer);const snapshot=structuredClone(state);const target=connectedSheet;saveQueue=saveQueue.then(()=>persistSnapshot(snapshot,target)).catch(err=>{lastPersistError=err;});}});


function abilityFields(a,prefix,index=''){return `<div class="fields"><label class="field">Nome<input ${prefix}="name" ${index} value="${escape(a.name)}" placeholder="Nome da habilidade"></label><label class="field">Tipo<input ${prefix}="type" ${index} value="${escape(a.type)}" placeholder="Ex.: Rookie, passiva, ativa…"></label><label class="field full">Descrição<textarea ${prefix}="description" ${index} placeholder="Cole o texto do livro ou escreva uma habilidade da campanha.">${escape(a.description)}</textarea></label></div>`;}
function trainerAbilities(t){return `<section class="card" style="margin-top:22px"><h2>Habilidades do treinador</h2><p class="input-note">Cinco espaços livres para habilidades de classe, Rookie, treinadas ou personalizadas.</p><div class="ability-list">${t.abilities.map((a,i)=>`<article class="ability-editor"><h3>Habilidade ${i+1}</h3>${abilityFields(a,'data-trainer-ability',`data-ability-index="${i}"`)}</article>`).join('')}</div></section>`;}
function abilityTab(p){return pokemonAbilityUI(p);}
function noteList(){const q=noteQuery.toLocaleLowerCase('pt-BR'),list=state.notes.filter(n=>`${n.title} ${n.text}`.toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>b.updated-a.updated);return list.length?list.map(n=>`<button class="note-entry ${noteDraft.id===n.id?'selected':''}" data-note="${n.id}"><strong>${escape(n.title)}</strong><small>${new Date(n.updated).toLocaleDateString('pt-BR')}</small><p>${escape(n.text.slice(0,140))}</p></button>`).join(''):'<p class="empty">Nenhuma nota encontrada.</p>';}
function catalogRecords(kind){const records= kind==='species'?[...species].sort((a,b)=>a.id-b.id):kind==='variants'?PERMANENT_VARIANTS:kind==='megaForms'?MEGAS:kind==='moves'?moves:kind==='abilities'?[...abilityCatalog,...state.trainer.abilities.filter(a=>a.name.trim()).map((a,i)=>({id:'trainer-'+i,name:a.name,pt:a.name,type:a.type,description:a.description}))]:allItems();return orderReferences(records,kind,kind==='items'?itemOrder:kind==='abilities'?abilityOrder:'name-en');}
function catalogResults(){const q=catalogQuery.toLocaleLowerCase('pt-BR');const list=catalogRecords(catalogTab).filter(r=>Object.values(r).join(' ').toLocaleLowerCase('pt-BR').includes(q));return list.length?list.map(r=>`<button class="catalog-item" data-reference="${catalogTab}:${r.id}">${['species','variants','megaForms'].includes(catalogTab)?`<img loading="lazy" src="${catalogTab==='species'?art(r.id):r.artId?art(r.artId):pendingFormArt}" alt="${escape(r.name)}">`:catalogTab==='items'?(itemImage(r)?`<img loading="lazy" src="${escape(itemImage(r))}" alt="${escape(r.pt)}">`:icon('bag')):icon(catalogTab==='moves'?'spark':'star')}<h3>${escape(r.pt||r.name)}</h3><small>${escape(r.name)}</small><p class="catalog-excerpt">${escape(['species','variants','megaForms'].includes(catalogTab)?r.types.join(' / '):r.type||r.category||'')}</p></button>`).join(''):'<div class="empty">Nenhuma referência encontrada.</div>';}
function referenceDialog(key){const [kind,id]=key.split(':'),r=catalogRecords(kind).find(r=>String(r.id)===id);if(!r)return;let body='';if(['species','variants','megaForms'].includes(kind))body=`<div class="reference-art"><img src="${kind==='species'?art(r.id):r.artId?art(r.artId):pendingFormArt}" alt="${escape(r.name)}"></div><p>${r.types.map(type).join(' ')}</p><p class="input-note">Pokédex #${r.speciesId||r.id}${r.defaultFormLabel?` · ${escape(r.defaultFormLabel)}`:''} · BST ${r.base.reduce((a,b)=>a+b,0)}</p><div class="stats-grid">${r.base.map((v,i)=>`<div class="stat"><span class="stat-name">${i===5?'Speed':STAT_LABELS[i]}</span><strong>${v}</strong></div>`).join('')}</div>${r.effect?`<p class="reference-description">${escape(r.effect)}</p>`:''}`;else if(kind==='items')body=`${itemImage(r)?`<div class="reference-art item"><img loading="lazy" src="${escape(itemImage(r))}" alt="${escape(r.pt)}"></div>`:''}<p class="input-note">${escape(r.name)} · ${escape(r.category)}</p><p class="reference-description">${escape(r.effect)}</p>`;else body=`<p class="input-note">${escape(r.name)} · ${escape(r.type)}</p><p class="reference-description">${escape(r.effect||r.description)}</p>${kind==='moves'?`<p class="panel-note">${escape(r.cat)} · ${damage(r.power)} de dano base · DT ${accuracy(r.acc)}</p>`:''}`;if(r.review&&r.review.translation!=='reviewed')body+='<p class="input-note">Tradução em desenvolvimento.</p>';if(r.originalDescription)body+=`<details class="official-reference"><summary>Descrição original dos jogos</summary><p>${escape(r.originalDescription)}</p></details>`;modal(escape(r.pt||r.name),body+button('close-dialog','Fechar','secondary'));}
function customItemDialog(){customItemImage='';modal('Item personalizado',`<form id="custom-item-form"><div class="fields" style="margin-top:0"><label class="field full">Nome<input name="name" maxlength="100" required></label><label class="field full">Descrição<textarea name="description" required placeholder="O que o item faz nesta campanha?"></textarea></label><label class="field">Categoria<select name="category"><option>Personalizados</option><option>Equipáveis</option><option>Pokéblocks</option><option>Berries</option></select></label><label class="field">Quantidade<input name="qty" type="number" min="1" max="9999" value="1" required></label><div class="field full"><span>Imagem do item</span><div class="custom-item-preview" id="custom-item-preview">${icon('image')}</div><label class="btn light upload-label">${icon('upload')} Escolher imagem<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" data-upload="item"></label></div></div>${modalActions('Criar item')}</form>`);}
function cultivationView(){const active=state.cultivation.filter(c=>c.kind==='greenhouse'&&!c.harvested),finished=state.cultivation.filter(c=>c.kind==='greenhouse'&&c.harvested),legacy=state.cultivation.filter(c=>c.kind!=='greenhouse');return `<div class="greenhouse-toolbar"><span>${active.length} plantio${active.length===1?'':'s'} em crescimento</span>${button('end-cultivation-session','Encerrar sessão','light','check',active.length?'':'disabled')}</div><div class="greenhouse-grid">${active.length?active.map(c=>cultivationCard(c)).join(''):'<div class="greenhouse-empty">'+greenhouseArt(null)+'<p>Nenhum plantio em crescimento.</p></div>'}</div>${finished.length?`<details class="cultivation-history"><summary>Plantios concluídos (${finished.length})</summary><div class="greenhouse-grid">${finished.slice().reverse().map(c=>cultivationCard(c)).join('')}</div></details>`:''}${legacy.length?`<details class="cultivation-history"><summary>Registros anteriores (${legacy.length})</summary>${legacy.map(c=>`<div class="note-row"><strong>${escape(c.name)}</strong><p>${escape(c.notes)}</p><small>${c.progress} / ${c.target} sessões registradas</small></div>`).join('')}<p class="input-note">Estes registros foram preservados. Para usar a regra automática, faça um novo plantio com uma Berry do inventário.</p></details>`:''}`;}
function eggsView(){return `<div class="card egg-section"><div class="section-line"><h3>Ovos de Pokémon</h3>${button('new-egg','Registrar ovo','light small','plus')}</div><p class="input-note">Os ovos ficam com a coleção. Ao eclodir, cada um cria uma ficha individual na reserva.</p><div class="inventory-grid">${state.eggs.length?state.eggs.map(e=>`<article class="item-card"><h3>${escape(e.name)}</h3><small>${e.speciesId?bySpecies(e.speciesId).name:'Espécie desconhecida'}</small><p>${escape(e.notes)}</p><label class="field">Sessões de incubação<input type="number" min="0" max="999" data-egg="${e.id}" value="${e.progress}"></label><button class="btn light small" data-hatch="${e.id}" style="margin-top:14px">Registrar eclosão</button></article>`).join(''):'<p class="input-note">Nenhum ovo registrado.</p>'}</div></div>`;}

function speciesDialog(){const p=selected();modal('Alterar espécie',`<form id="species-form"><div id="change-species-picker"></div><p class="input-note">PE, treinos, habilidade, movimentos, item equipado e demais registros serão mantidos. Base Stats, tipos, Rank e imagem normal/shiny acompanham a nova espécie. A imagem personalizada é preservada.</p>${modalActions('Alterar espécie')}</form>`);mountSpeciesPicker($('#change-species-picker'),{catalog:species,initialId:p.speciesId});}
function retireDialog(){const p=selected();modal('Retirar da coleção',`<form id="retire-form"><p class="input-note">${escape(p.nickname||bySpecies(p.speciesId).name)} sairá da coleção e da equipe. A ficha ficará em Retirados para consulta e restauração. O item equipado volta a ficar disponível no inventário.</p><label class="field">Motivo<select name="reason"><option>Libertado</option><option>Despedida</option><option>Falecido</option><option>Ficha de teste</option><option>Outro</option></select></label>${modalActions('Retirar da coleção')}</form>`);}
function retiredDialog(){const list=state.retiredPokemon||[];modal('Pokémon retirados',list.length?list.map(p=>`<article class="retired-entry">${pokeImage(p,'thumbnail')}<div><strong>${escape(p.nickname||bySpecies(p.speciesId).name)}</strong><small>${escape(bySpecies(p.speciesId).name)} · ${escape(p.retired?.reason||'Retirado')}</small></div><button class="btn light small" data-restore-pokemon="${p.id}">Restaurar</button><button class="btn secondary small" data-delete-pokemon="${p.id}">Apagar definitivamente</button></article>`).join(''):'<p class="empty">Nenhum Pokémon retirado.</p>');}

function resolveAbility(value){const q=String(value||'').trim().toLocaleLowerCase('pt-BR');return abilityCatalog.find(a=>[a.id,a.name,a.pt,`${a.pt} / ${a.name}`].some(v=>v.toLocaleLowerCase('pt-BR')===q));}
function currentAbility(p){return abilityCatalog.find(a=>a.id===p.abilityId);}
function abilityDescription(p){const changed=activeMega(p)||permanentVariant(p,bySpecies(p.speciesId));if(changed?.ability)return `<h3>${escape(changed.ability)} · ${activeMega(p)?'Mega':'Variante'}</h3><p>Adaptação RPG em desenvolvimento. A habilidade habitual é preservada.</p>`;const a=currentAbility(p);return a?`<h3>${escape(a.pt)} <small>/ ${escape(a.name)}</small></h3><p>${escape(a.description)}</p><button class="inline-link" data-reference="abilities:${a.id}">Consultar no Pokédex</button>`:`<p>${p.abilityQuery?'Habilidade não encontrada nesta amostra do Pokédex.':'Digite o nome para consultar a habilidade no Pokédex.'}</p>`;}
function pokemonAbilityUI(p){return `<section class="pokemon-ability"><label class="field" for="pokemon-ability">${activeMega(p)||permanentVariant(p,bySpecies(p.speciesId))?'Habilidade habitual':'Habilidade do Pokémon'}<input id="pokemon-ability" list="ability-options" autocomplete="off" placeholder="Nome original ou em português…" value="${escape(p.abilityQuery||currentAbility(p)?.name||'')}"></label><datalist id="ability-options">${abilityCatalog.map(a=>`<option value="${escape(a.name)}">${escape(a.pt)}</option><option value="${escape(a.pt)}">${escape(a.name)}</option>`).join('')}</datalist><div class="ability-description">${abilityDescription(p)}</div></section>`;}
function stageControls(p,index,label){const value=p.stages[index]||0;return `<div class="combat-stage"><button type="button" data-stage-step="${index}" data-delta="-1" aria-label="Reduzir estágio de ${label}" ${value<=-6?'disabled':''}>−</button><span aria-label="Estágio de ${label}">${value>0?'+':''}${value}</span><button type="button" data-stage-step="${index}" data-delta="1" aria-label="Aumentar estágio de ${label}" ${value>=6?'disabled':''}>+</button></div>`;}
function combatStatsHTML(p,s,c){const values=combatValues(c.values,p.stages);return `<div class="stats-grid combat-stats">${values.map((v,i)=>`<div class="stat ${v!==c.values[i]?'modified':''}"><div class="stat-name">${['HP máximo','Ataque','Defesa','At. especial','Def. especial','Evasão'][i]}</div><strong>${v}${[1,3].includes(i)?'d4':''}</strong><small>Base ${c.values[i]}${[1,3].includes(i)?'d4':''}</small>${i?stageControls(p,({1:0,2:1,3:2,4:3,5:6})[i],STAT_LABELS[i]):'<small>Sem estágio</small>'}</div>`).join('')}</div>`;}
function accuracyControls(p){return `<div class="accuracy-control"><div><strong>Accuracy</strong><small>+1 estágio reduz a DT em 1; −1 aumenta em 1.</small></div>${stageControls(p,5,'Accuracy')}</div>`;}
function trainerRank(prestige){const name=rank(prestige),id=({'Poké Ball':'poke-ball','Great Ball':'great-ball','Ultra Ball':'ultra-ball','Master Ball':'master-ball'})[name];return `<span class="trainer-rank" role="img" aria-label="Rank do treinador: ${name}" title="${name} · ${prestige} pontos de Prestígio">${id?`<img src="${itemArt(id)}" alt="">`:'<small>Básico</small>'}</span>`;}
const originalPokemonView=pokemonView;pokemonView=function(){return originalPokemonView()+eggsView();};
function eggDialog(egg){modal(egg?'Eclosão do ovo':'Registrar ovo',`<form id="${egg?'hatch':'egg'}-form" ${egg?`data-egg-id="${egg.id}"`:''}><div class="fields" style="margin-top:0"><label class="field full">${egg?'Apelido do novo parceiro':'Nome do ovo'}<input name="name" maxlength="100" value="${escape(egg?.name||'')}" required></label><label class="field full">Espécie<select name="speciesId">${egg?'':'<option value="">Desconhecida</option>'}${species.map(s=>`<option value="${s.id}" ${egg?.speciesId===s.id?'selected':''}>${escape(s.name)}</option>`).join('')}</select></label>${egg?'':`<label class="field full">Anotações<textarea name="notes"></textarea></label>`}</div>${modalActions(egg?'Criar ficha do parceiro':'Registrar ovo')}</form>`);}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;let handled=true;
 if(b.dataset.condition)return;
 if(b.dataset.loadBackup){loadBackup(b.dataset.loadBackup);e.stopImmediatePropagation();return;}
 if(b.dataset.stageStep!==undefined){const p=selected(),i=Number(b.dataset.stageStep);p.stages[i]=clamp((p.stages[i]||0)+Number(b.dataset.delta),-6,6);save();renderDetail();}
 else if(b.dataset.contestTab){contestTab=b.dataset.contestTab;renderDetail();}
 else if(b.dataset.contestDelta!==undefined){const p=selected(),i=Number(b.dataset.contestDelta);const gained=trainContest(p,i);save();renderDetail();toast(p.contest[i]>=10?"Atributo no máximo de 10.":gained?"+1 ponto de Contest!":"Progresso do treino de Contest registrado.");}
 else if(b.dataset.inventoryTab){inventoryTab=b.dataset.inventoryTab;inventoryCategory='all';fullRender();}
 else if(b.dataset.useBlock){const block=state.pokeblocks.find(p=>p.id===b.dataset.useBlock);if(block&&block.qty>0){block.qty--;save(true);fullRender();toast('Uma unidade consumida. Resolva os efeitos e a duração narrativa com o Mestre.');}}
 else if(b.dataset.catalogTab){catalogTab=b.dataset.catalogTab;fullRender();}
 else if(b.dataset.reference)referenceDialog(b.dataset.reference);
 else if(b.dataset.note){const n=state.notes.find(n=>n.id===b.dataset.note);noteDraft={...n};fullRender();}
 else if(b.dataset.restorePokemon){const result=restorePokemon(state,b.dataset.restorePokemon);save(true);dialog.close();collectionFilter='all';collectionQuery='';fullRender();toast(result?.itemUnavailable?'Ficha restaurada na reserva. O antigo held item está indisponível.':'Ficha restaurada na reserva.');}
 else if(b.dataset.hatch)eggDialog(state.eggs.find(e=>e.id===b.dataset.hatch));
 else switch(b.dataset.action){
  case 'change-species':speciesDialog();break;
  case 'retire-pokemon':retireDialog();break;
  case 'retired-list':retiredDialog();break;
  case 'new-note':noteDraft={id:'',title:'',text:''};fullRender();break;
  case 'custom-item':customItemDialog();break;
  case 'new-egg':eggDialog();break;
  case 'choose-ability':modal('Selecionar habilidade de referência',`<form id="choose-ability-form"><label class="field">Habilidade<select name="ability">${abilityCatalog.map(a=>`<option value="${a.id}">${a.pt} / ${a.name}</option>`).join('')}</select></label>${modalActions('Usar como base')}</form>`);break;
  case 'prepare-block':commitBlock();break;
  case 'new-cultivation':plantDialog();break;
  case 'end-cultivation-session':{const harvests=endCultivationSession(state);save(true);fullRender();toast(harvests.length?'Colheita no inventário: '+harvests.map(h=>`${h.qty} × ${h.name}`).join(', ')+'.':'Sessão registrada na estufa.');break;}
  default:handled=false;
 }
 if(handled)e.stopImmediatePropagation();
},true);
document.addEventListener('input',e=>{
 const el=e.target;let changed=true;
 if(el.dataset.trainerAbility){const a=state.trainer.abilities[Number(el.dataset.abilityIndex)];a[el.dataset.trainerAbility]=el.value;}
 else if(el.id==='pokemon-ability'){const p=selected(),a=resolveAbility(el.value);p.abilityQuery=el.value;p.abilityId=a?.id||'';const body=$('.ability-description');if(body)body.innerHTML=abilityDescription(p);}
 else if(el.dataset.contest!==undefined)selected().contest[Number(el.dataset.contest)]=Math.floor(clamp(el.value,0,10));
 else if(el.dataset.egg){state.eggs.find(v=>v.id===el.dataset.egg).progress=Math.floor(clamp(el.value,0,999));}
 else if(el.dataset.cultivation){const c=state.cultivation.find(v=>v.id===el.dataset.cultivation);c[el.dataset.cultivationKey]=Math.floor(clamp(el.value,el.dataset.cultivationKey==='target'?1:0,999));}
 else if(el.dataset.tfield==='prestige'){state.trainer.prestige=Math.floor(clamp(el.value,0,99999));const badge=$('.trainer-rank');if(badge)badge.outerHTML=trainerRank(state.trainer.prestige);}
 else if(el.dataset.tfield&&el.type!=='number')state.trainer[el.dataset.tfield]=el.value;
 else changed=false;
 if(changed)save(el.id==='pokemon-ability');
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.condition){const p=selected(),v=el.dataset.condition;p.conditions=el.checked?[...new Set([...p.conditions,v])]:p.conditions.filter(c=>c!==v);save();}});
document.addEventListener('submit',e=>{
 const f=e.target,v=new FormData(f);let handled=true;
 switch(f.id){
  case 'species-form':{if(!species.some(s=>s.id===Number(v.get('speciesId'))))return;changeSpecies(selected(),v.get('speciesId'));normalizeHP();toast('Espécie atualizada. Dados individuais preservados.');break;}
  case 'retire-form':{retirePokemon(state,selected().id,String(v.get('reason')));toast('Ficha retirada da coleção. Você pode restaurá-la em Retirados.');break;}
  case 'note-form':{const title=String(v.get('title')).trim(),text=String(v.get('text')).trim();if(!title||!text){toast('Escreva o título e o texto da nota.');break;}const n={id:noteDraft.id||crypto.randomUUID(),title,text,updated:Date.now()},i=state.notes.findIndex(x=>x.id===n.id);if(i>=0)state.notes[i]=n;else state.notes.push(n);noteDraft={...n};toast('Nota salva.');break;}
  case 'custom-item-form':{const name=String(v.get('name')).trim(),effect=String(v.get('description')).trim();if(!name||!effect){toast('Preencha nome e descrição.');break;}const id='custom-'+crypto.randomUUID();state.customItems.push({id,name,pt:name,effect,category:String(v.get('category')),image:customItemImage,custom:true});state.inventory.push({id,qty:Math.floor(clamp(v.get('qty'),1,9999))});inventoryTab=v.get('category')==='Pokéblocks'?'blocks':'items';inventoryCategory='all';inventoryQuery='';toast('Item personalizado criado.');break;}
  case 'choose-ability-form':{const a=abilityCatalog.find(a=>a.id===v.get('ability'));selected().abilityId=a.id;selected().abilityQuery=a.name;break;}
  case 'cultivation-form':{try{const item=byItem(String(v.get('berry')));plantBerry(state,item,Number(v.get('result')),String(v.get('notes')));toast('Plantio registrado. Uma Berry foi consumida.');}catch(err){e.preventDefault();e.stopImmediatePropagation();$('#form-error').textContent=err.message;return;}break;}
  case 'egg-form':state.eggs.push({id:crypto.randomUUID(),name:String(v.get('name')).trim(),speciesId:Number(v.get('speciesId'))||null,notes:String(v.get('notes')),progress:0});break;
  case 'hatch-form':{const egg=state.eggs.find(x=>x.id===f.dataset.eggId),p=makePokemon(Number(v.get('speciesId')),String(v.get('name')).trim());p.notes=egg.notes;state.pokemon.push(p);state.selected=p.id;state.eggs=state.eggs.filter(x=>x.id!==egg.id);detailTab='overview';collectionFilter='all';collectionQuery='';toast('Eclosão registrada. Nova ficha criada na reserva.');break;}
  default:handled=false;
 }
 if(handled){e.preventDefault();e.stopImmediatePropagation();normalizeHP();save();dialog.close();fullRender();}
},true);



function greenhouseArt(c){const stage=!c?'empty':c.harvested?(c.yield?'fruit':'failed'):c.progress===0?'seed':'growing';const plant=stage==='seed'?'<path d="M146 144q8-10 16 0" fill="#886445"/>':stage==='empty'?'':stage==='failed'?'<path d="M154 143v-33q-13-18-28-9m28 28q14-16 26-6" fill="none" stroke="#a58b65" stroke-width="5"/>':`<path d="M154 145v-53m0 29q-27-3-32-23 24-5 32 23m0-12q24-2 28-23-23-3-28 23" fill="#74ae73" stroke="#448366" stroke-width="3"/>${stage==='fruit'?'<g fill="#bd699b" stroke="#95517a" stroke-width="2"><circle cx="131" cy="114" r="8"/><circle cx="174" cy="103" r="8"/><circle cx="156" cy="88" r="8"/></g>':'<circle cx="155" cy="86" r="5" fill="#f0c577"/>'}`;return `<svg class="greenhouse-art" viewBox="0 0 310 205" role="img" aria-label="Estufa portátil: ${({empty:'vazia',seed:'plantio',growing:'crescimento',fruit:'frutos maduros',failed:'plantio sem frutos'})[stage]}"><ellipse cx="155" cy="181" rx="110" ry="10" fill="#e1ece6"/><path d="M54 151V87q0-59 101-59t101 59v64" fill="#e8f7f2" stroke="#5aada6" stroke-width="5"/><path d="M155 29v120M56 86h198M96 45v103m118-103v103" fill="none" stroke="#b5d9ce" stroke-width="3"/><path d="M79 66q17-21 49-23" fill="none" stroke="white" stroke-width="7" stroke-linecap="round"/><path d="M81 144q74-22 148 0v18H81z" fill="#977255"/>${plant}<rect x="43" y="151" width="224" height="27" rx="10" fill="#EE7329" stroke="#d45d1b" stroke-width="3"/><rect x="126" y="165" width="57" height="15" rx="6" fill="#5AC5BD"/><circle cx="243" cy="163" r="4" fill="#fff0cd"/></svg>`;}
function cultivationCard(c){const phase=c.harvested?(c.yield?'Colhido':'Sem produção'):c.progress?'Crescendo':'Plantado';return `<article class="greenhouse-card">${greenhouseArt(c)}<div class="greenhouse-title"><h3>${escape(c.name)}</h3><span>${phase}</span></div><div class="greenhouse-numbers"><div><strong>${c.remaining}</strong><small>Sessões restantes</small></div><div><strong>${c.yield}</strong><small>${c.harvested?'Berries produzidas':'Berries previstas'}</small></div></div><div class="progress-bar"><span style="width:${c.progress/c.target*100}%"></span></div><p class="input-note">Teste: ${c.testResult} · ${c.target} sessões no total${c.harvested&&c.yield?' · Adicionadas ao inventário':''}</p>${c.yield===0?'<p class="input-note">O plantio não produzirá frutos.</p>':''}${c.notes?`<p class="cultivation-notes">${escape(c.notes)}</p>`:''}</article>`;}
function plantPreview(){const input=$('#cultivation-result');if(!input||input.value===''){$('#plant-preview').innerHTML='';return;}try{const outcome=cultivationOutcome(Number(input.value));$('#plant-preview').innerHTML=`<div class="panel-note">${outcome.sessions} sessões · ${outcome.yield} ${outcome.yield===1?'Berry':'Berries'}${outcome.yield===0?'<br>Falha no plantio: a Berry será consumida e não haverá frutos.':''}</div>`;}catch{$('#plant-preview').textContent='Informe um resultado inteiro.';}}
function plantDialog(){const berries=state.inventory.map(e=>byItem(e.id)).filter(i=>i?.category==='Berries'&&available(i.id)>0);if(!berries.length){modal('Novo plantio','<p class="input-note">Você precisa de uma Berry disponível no inventário. Berries equipadas não podem ser plantadas.</p>'+button('close-dialog','Fechar'));return;}modal('Novo plantio',`<form id="cultivation-form"><div class="fields" style="margin-top:0"><label class="field full">Berry<select name="berry">${berries.map(i=>`<option value="${i.id}">${escape(i.pt)} · ${available(i.id)} disponíveis</option>`).join('')}</select></label><label class="field full">Resultado total do teste de Cultivo<input id="cultivation-result" name="result" type="number" step="1" required placeholder="Some os dados e a perícia"></label><label class="field full">Anotações<textarea name="notes"></textarea></label></div><div id="plant-preview"></div><p class="input-note">Plantar consome uma Berry. Ao encerrar as sessões necessárias, os frutos entram no inventário automaticamente.</p>${modalActions('Plantar')}</form>`);}
document.addEventListener('input',e=>{if(e.target.id==='cultivation-result')plantPreview();});


let blockDraft={ingredients:['','',''],mode:'single',flavors:[],allocation:[],result:''};
function blockArt(){return `<svg class="block-art" viewBox="0 0 100 100" role="img" aria-label="Pokéblock"><path d="m50 12 34 19-34 20L16 31z" fill="#a5e2d9"/><path d="m16 31 34 20v38L16 69z" fill="#5ac5bd"/><path d="m50 51 34-20v38L50 89z" fill="#39968f"/><g fill="#e7faf5"><circle cx="35" cy="51" r="3"/><circle cx="27" cy="63" r="3"/><circle cx="42" cy="72" r="3"/></g></svg>`;}
function pokeblocksView(){return `<div class="blocks-layout"><section class="card blender"><div class="blender-heading">${icon('spark')}<h2>Berry Blender</h2></div><div class="berry-slots">${blockDraft.ingredients.map((id,i)=>`<label class="field"><span>Berry ${i+1}</span><select data-blend-berry="${i}"><option value="">Selecionar…</option>${state.inventory.filter(e=>byItem(e.id)?.category==='Berries'&&byItem(e.id)?.flavors).map(e=>{const b=byItem(e.id);return `<option value="${b.id}" ${id===b.id?'selected':''}>${escape(b.pt)} (${available(b.id)} disponíveis)</option>`}).join('')}</select><span class="berry-slot-art">${id?`<img src="${escape(itemImage(byItem(id)))}" alt="${escape(byItem(id).pt)}">`:icon('leaf')}</span></label>`).join('')}</div><div id="blend-mix"></div><div class="fields"><label class="field full">Resultado total de Culinária<input id="blend-result" type="number" step="1" value="${escape(blockDraft.result)}" placeholder="Some os dados e a perícia"></label></div><div id="blend-preview"></div>${button('prepare-block','Preparar e guardar','primary','plus')}<p id="blend-error" class="form-error" role="alert"></p><p class="input-note">Três Berries por Pokéblock. Os ingredientes são consumidos ao preparar.</p></section><section class="card"><div class="blender-heading">${icon('bag')}<h2>Pokéblock Case</h2></div><div class="block-case">${blockCase()}</div><p class="input-note">Duração em horas narrativas. Consumir reduz o estoque; preferências e bônus no Pokémon ainda são resolvidos na mesa.</p></section></div><details class="block-legacy"><summary>Itens personalizados de Pokéblock</summary><div class="inventory-grid" id="inventory-grid">${inventoryCards()}</div></details>`;}
function refreshBlend(){if(!$('#blend-mix'))return;const berries=blockDraft.ingredients.map(byItem),totals=flavorTotals(berries),ready=berries.every(Boolean),options=ready?flavorOptions(totals,blockDraft.mode):[];if(!options.some(o=>o.join(',')===blockDraft.flavors.join(',')))blockDraft.flavors=options[0]||[];const power=potency(blockDraft.flavors.reduce((n,i)=>n+totals[i],0));if(blockDraft.allocation.length!==blockDraft.flavors.length||blockDraft.allocation.reduce((a,b)=>a+b,0)!==power)blockDraft.allocation=blockDraft.flavors.map((_,i)=>blockDraft.mode==='single'?power:power?i===0?power-1:1:0);$('#blend-mix').innerHTML=`<div class="flavor-totals">${FLAVORS.map((f,i)=>`<div style="--flavor:${f.hex}"><span>${f.name}</span><strong>${totals[i]}</strong></div>`).join('')}</div><div class="fields"><label class="field">Modo<select id="blend-mode"><option value="single" ${blockDraft.mode==='single'?'selected':''}>Cor única</option><option value="double" ${blockDraft.mode==='double'?'selected':''}>Cor dupla</option></select></label><label class="field">Sabores<select id="blend-flavors" ${options.length?'':'disabled'}>${options.length?options.map(o=>`<option value="${o.join(',')}" ${o.join(',')===blockDraft.flavors.join(',')?'selected':''}>${o.map(i=>FLAVORS[i].name).join(' + ')}</option>`).join(''):'<option>Selecione as Berries</option>'}</select></label></div>${blockDraft.flavors.length?`<div class="block-potency"><strong>${power} pontos de potência</strong>${blockDraft.mode==='double'&&power?`<label class="field">Pontos em ${FLAVORS[blockDraft.flavors[0]].name}<select id="blend-allocation">${Array.from({length:power-1},(_,i)=>i+1).map(n=>`<option value="${n}" ${blockDraft.allocation[0]===n?'selected':''}>${n} + ${power-n} em ${FLAVORS[blockDraft.flavors[1]].name}</option>`).join('')}</select></label>`:''}</div>`:''}`;refreshBlockPreview();}
function getBlockPreview(){if(blockDraft.ingredients.some(id=>!id)||blockDraft.result==='')return null;return blockRecipe(blockDraft.ingredients.map(byItem),blockDraft.mode,blockDraft.flavors,blockDraft.allocation,Number(blockDraft.result));}
function refreshBlockPreview(){const box=$('#blend-preview');if(!box)return;try{const b=getBlockPreview();box.innerHTML=b?blockSummary(b):'<p class="input-note">Escolha três Berries e informe o teste para ver o resultado.</p>';$('#blend-error').textContent='';}catch(err){box.innerHTML=`<p class="input-note">${escape(err.message)}</p>`;}}
function blockSummary(b){const effects=describeBlock(b);return `<div class="block-summary"><div class="block-summary-head">${blockArt()}<div><strong>${escape(b.color)}</strong><small>${escape(b.quality)}</small><span class="block-colors">${b.flavors.map(i=>`<i style="background:${FLAVORS[i].hex}" title="${FLAVORS[i].name}"></i>`).join('')}</span></div></div><dl><dt>Batalha</dt><dd>${effects.battle}</dd><dt>Contest</dt><dd>${effects.contest}</dd><dt>Duração base</dt><dd>${b.hours&&b.potency?`${b.hours} ${b.hours===1?'hora':'horas'}`:'Sem benefício especial'}</dd></dl></div>`;}
function blockCase(){const list=(state.pokeblocks||[]).filter(b=>b.qty>0);return list.length?list.map(b=>`<article class="case-entry">${blockSummary(b)}<div class="case-actions"><span>${b.qty} unidade${b.qty===1?'':'s'}</span><button class="btn light small" data-use-block="${b.id}">Consumir unidade</button></div><details><summary>Receita</summary><p>${b.ingredients.map(id=>escape(byItem(id)?.pt||id)).join(' + ')}</p><p>${b.flavors.map((f,i)=>`${FLAVORS[f].name}: ${b.allocation[i]} ponto(s)`).join(' · ')} · Teste: ${b.testResult}</p></details></article>`).join(''):'<div class="empty block-empty">'+blockArt()+'<p>Nenhum Pokéblock guardado.</p></div>';}
function commitBlock(){try{if(!getBlockPreview())throw Error('Escolha três Berries e informe o resultado do teste.');prepareBlock(state,allItems(),{...blockDraft,result:Number(blockDraft.result)});save(true);fullRender();toast('Pokéblock guardado. Três Berries foram consumidas.');}catch(err){$('#blend-error').textContent=err.message;}}
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.blendBerry!==undefined){blockDraft.ingredients[Number(el.dataset.blendBerry)]=el.value;blockDraft.flavors=[];blockDraft.allocation=[];fullRender();}else if(el.id==='blend-mode'){blockDraft.mode=el.value;blockDraft.flavors=[];blockDraft.allocation=[];refreshBlend();}else if(el.id==='blend-flavors'){blockDraft.flavors=el.value.split(',').map(Number);blockDraft.allocation=[];refreshBlend();}else if(el.id==='blend-allocation'){const power=potency(blockDraft.flavors.reduce((n,i)=>n+flavorTotals(blockDraft.ingredients.map(byItem))[i],0));blockDraft.allocation=[Number(el.value),power-Number(el.value)];refreshBlockPreview();}});
document.addEventListener('input',e=>{if(e.target.id==='blend-result'){blockDraft.result=e.target.value;refreshBlockPreview();}});

let currentAccount=null,connectedSheet=null,remoteSheets=[],catalogEntries=[],catalogStamp='',editorId='',accountMessage='',lastPersistError=null;
async function dbPut(key,value){if(!db)return;return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function persistSnapshot(snapshot,target){lastPersistError=null;if(!target)return writeState(snapshot);await dbPut('server-cache:'+target.id,snapshot);const updated=await request('/characters/'+target.id,{method:'PATCH',body:{data:snapshot,version:target.version}});target.version=updated.version;remoteSheets=remoteSheets.map(c=>c.id===updated.id?{...c,name:updated.name,version:updated.version}:c);if(view==='account')fullRender();}
async function flushEdits(){save(true);await saveQueue;if(lastPersistError)throw lastPersistError;}
async function refreshCatalog(render=true){if(!currentAccount)return;const stamp=(await request('/catalog/version')).version;if(stamp!==catalogStamp){const entries=await request('/catalog');catalogEntries=entries;catalogStamp=stamp;applyCatalog(entries);if(render)fullRender();}}
async function refreshAccount(){remoteSheets=await request('/characters');await refreshCatalog(false);}
async function openRemoteSheet(cid,force=false){try{if(!force)await flushEdits();else if(connectedSheet)await dbPut('server-cache:'+connectedSheet.id,structuredClone(state));const c=await request('/characters/'+cid),loaded=importSheet(await materializeAssets(c.data));connectedSheet={id:c.id,version:c.version,ownerId:c.ownerId,campaignId:c.campaignId,kind:c.kind};if(loaded.sheetName===undefined)loaded.sheetName=c.name;state=loaded;sessionStorage.setItem('rotom-sheet-'+currentAccount.id,c.id);collectionQuery='';collectionFilter='all';detailTab='overview';normalizeHP();view='trainer';lastPersistError=null;setSaveStatus(hosted?'Salvo no servidor':'Salvo no banco local');fullRender();}catch(err){accountMessage=err.message;toast(err.message);}}
async function openLocalDraft(){try{await flushEdits();const draft=await readState();connectedSheet=null;state=migrate(draft||blankSheet('Novo treinador'));if(currentAccount)sessionStorage.removeItem('rotom-sheet-'+currentAccount.id);normalizeHP();view='trainer';lastPersistError=null;setSaveStatus('Salvo neste navegador');fullRender();}catch(err){toast(err.message);}}
function accountView(){if(!currentAccount)return `${heading('',hosted?'Sua conta':'Conta local','')}<p class="panel-note">${hosted?'Entre para guardar suas fichas na conta e participar das campanhas. Seu rascunho permanece neste navegador.':'Contas e fichas ficam somente neste PC. A primeira conta criada administra o catálogo. Seu rascunho atual permanece no navegador.'}</p><div class="grid-two"><section class="card"><h2>Entrar</h2><form id="login-form"><div class="fields"><label class="field full">E-mail<input type="email" name="email" autocomplete="username" required></label><label class="field full">Senha<input type="password" name="password" autocomplete="current-password" required></label></div><button class="btn primary" type="submit">Entrar</button></form></section><section class="card"><h2>${hosted?'Criar conta':'Criar conta neste PC'}</h2><form id="register-form"><div class="fields"><label class="field full">Seu nome<input name="name" maxlength="100" autocomplete="name" required></label><label class="field full">E-mail<input type="email" name="email" autocomplete="email" required></label><label class="field full">Senha<input type="password" name="password" minlength="10" maxlength="256" autocomplete="new-password" required></label></div><p class="input-note">Pelo menos 10 caracteres. Esta versão não envia e-mails automaticamente.</p><button class="btn primary" type="submit">Criar conta</button></form></section></div>${accountMessage?`<p class="form-error">${escape(accountMessage)}</p>`:''}`;
 return `${heading('','Conta e fichas','',button('logout-account','Sair da conta','secondary'))}<div class="panel-note"><strong>${escape(currentAccount.name)}</strong> · ${escape(currentAccount.email)}${currentAccount.catalog_admin?' · Administrador do catálogo':''}<br>${connectedSheet?(hosted?'Ficha aberta no servidor: ':'Ficha aberta no banco local: ')+escape(state.sheetName||state.trainer.name):'Modo rascunho do navegador'}</div>${accountMessage?`<p class="form-error">${escape(accountMessage)}</p>`:''}<div class="grid-two"><section class="card"><h2>Fichas acessíveis</h2>${remoteSheets.length?remoteSheets.map(c=>`<div class="saved-sheet"><div><strong>${escape(c.name)}</strong><small>${c.ownerId===currentAccount.id?'Sua ficha':'Ficha da campanha'} · ${c.kind==='npc'?'NPC':'Personagem'} · revisão ${c.version}</small></div><button class="btn light small" data-open-remote="${c.id}">Abrir ficha</button>${c.ownerId===currentAccount.id?`<button class="btn light small" data-rename-sheet="${c.id}">Renomear ficha</button><button class="btn secondary small" data-archive-sheet="${c.id}">Excluir ficha</button>`:''}</div>`).join(''):'<p class="empty">Nenhuma ficha no banco ainda.</p>'}<div class="footer-action">${button('local-draft','Abrir rascunho do navegador','secondary small')}${button('blank-draft','Novo rascunho vazio','secondary small')}</div>${connectedSheet?button('reload-remote','Recarregar ficha do banco','secondary small'):''}</section><section class="card"><h2>Guardar uma ficha na conta</h2><form id="create-remote-form"><div class="fields"><label class="field full">Nome da ficha<input name="name" value="${escape(state.trainer.name)}" maxlength="100" required></label><label class="field full">Conteúdo<select name="source"><option value="current">Copiar a ficha aberta, com Pokémon e inventário</option><option value="empty">Começar uma ficha vazia</option></select></label></div><p class="input-note">A cópia é independente. O rascunho original continua guardado no navegador.</p><button type="submit" class="btn primary">Guardar e abrir</button></form></section></div>${currentAccount.catalog_admin?`<div class="card" style="margin-top:22px"><h2>Catálogo central</h2><p class="input-note">As adaptações publicadas aqui chegam às fichas conectadas, sem alterar seus dados individuais.</p>${button('author-page','Editar catálogo','primary','grid')}${button('seed-catalog',catalogEntries.length?'Completar amostra do protótipo':'Carregar amostra do protótipo','light')}</div>`:''}`;}
function authorView(){if(!currentAccount?.catalog_admin)return '<p class="empty">Entre com a conta administradora do catálogo.</p>';const entry=catalogEntries.find(e=>e.id===editorId)||catalogEntries[0];if(!entry)return `${heading('','Editor do catálogo','')}<div class="card"><p class="input-note">O banco ainda não tem referências. Você pode carregar a amostra já usada no protótipo; a planilha completa será importada em uma próxima etapa.</p>${button('seed-catalog','Carregar amostra do protótipo','primary')}</div>`;editorId=entry.id;const numeric=(key,labels)=>`<label class="override-option"><input type="checkbox" name="override-${key}" ${entry.rpg[key]!==undefined?'checked':''}> Adaptar ${key==='base'?'Base Stats':'intensidades de sabor'} para o RPG</label><div class="numeric-catalog">${labels.map((label,i)=>`<label class="field">${label}<input type="number" min="0" max="9999" step="1" name="${key}-${i}" value="${(entry.rpg[key]||entry.official[key]||[])[i]??0}"></label>`).join('')}</div>`;return `${heading('','Editor do catálogo','',button('account-page','Conta e fichas','secondary'))}<div class="card"><label class="field">Referência<select id="catalog-editor-entry">${catalogEntries.map(e=>`<option value="${escape(e.id)}" ${entry.id===e.id?'selected':''}>${escape(categoryNames[e.kind]||e.kind)} · ${escape(e.official.name||e.id)}</option>`).join('')}</select></label><p class="input-note">Revisão ${entry.version} · Publicar afeta todas as fichas conectadas que usam esta referência. Desmarcar uma adaptação numérica volta a usar o valor oficial.</p><form id="catalog-editor-form">${reviewFields(entry)}<div class="fields"><label class="field full">Nome em português<input name="translatedName" value="${escape(entry.translations.name||'')}" maxlength="160"></label><label class="field full">Descrição traduzida<textarea name="translatedDescription">${escape(entry.translations.description||'')}</textarea></label><label class="field full">Efeito / descrição adaptada para o RPG<textarea name="rpgDescription">${escape(entry.rpg.description||'')}</textarea></label></div>${['species','variants','megaForms'].includes(entry.kind)?numeric('base',['HP','Ataque','Defesa','At. especial','Def. especial','Speed']):''}${Array.isArray(entry.official.flavors)?numeric('flavors',FLAVORS.map(f=>f.name)):''}${entry.kind==='moves'?`<label class="override-option"><input type="checkbox" name="override-power" ${Object.hasOwn(entry.rpg,'power')?'checked':''}> Adaptar potência base</label><label class="field">Potência (vazio para Status)<input name="power" type="number" min="0" max="9999" value="${(Object.hasOwn(entry.rpg,'power')?entry.rpg.power:entry.official.power)??''}"></label><label class="override-option"><input type="checkbox" name="override-acc" ${Object.hasOwn(entry.rpg,'acc')?'checked':''}> Adaptar precisão</label><label class="field">Precisão (vazio para movimento sem teste)<input name="acc" type="number" min="0" max="100" value="${(Object.hasOwn(entry.rpg,'acc')?entry.rpg.acc:entry.official.acc)??''}"></label>`:''}<div class="dialog-actions"><button class="btn primary" type="submit">Publicar alterações</button></div><p id="catalog-editor-message" class="form-error" role="status"></p></form><details class="official-reference"><summary>Dados oficiais preservados</summary><pre>${escape(JSON.stringify(entry.official,null,2))}</pre></details></div>`;}
async function publishCatalog(form){const e=catalogEntries.find(e=>e.id===editorId),v=new FormData(form),rpg={...e.rpg},translations={...e.translations,name:String(v.get('translatedName')).trim(),description:String(v.get('translatedDescription')).trim()};rpg.description=String(v.get('rpgDescription')).trim();for(const[key,n]of [['base',6],['flavors',5]]){if(v.has('override-'+key))rpg[key]=Array.from({length:n},(_,i)=>{const number=Number(v.get(`${key}-${i}`));if(!Number.isInteger(number)||number<0||number>9999)throw Error('Informe valores numéricos válidos.');return number;});else delete rpg[key];}for(const key of ['power','acc']){if(v.has('override-'+key)){const value=String(v.get(key));rpg[key]=value===''?null:Number(value);}else if(e.kind==='moves')delete rpg[key];}await request('/catalog',{method:'PUT',body:{entry:{...e,translations,rpg,review:Object.fromEntries(['official','translation','rpg'].map(k=>[k,String(v.get('review-'+k))]))},version:e.version}});await refreshCatalog(false);fullRender();toast('Alterações publicadas no catálogo central.');}
function blankSheet(name){const s=migrate(initialState());s.pokemon=[];s.selected=null;s.inventory=[];s.cultivation=[];s.eggs=[];s.notes=[];s.pokeblocks=[];s.retiredPokemon=[];s.customItems=[];s.trainer={...s.trainer,name,player:currentAccount?.name||'',className:'',profession:'',portrait:'',story:'',goals:'',bonds:'',money:0,level:5,prestige:0,aura:0,survival:[0,0,0,0],hp:1,attributes:[0,0,0],abilities:Array.from({length:5},()=>({name:'',type:'',description:''})),skills:skills.map(name=>({name,bonus:0,mastery:false}))};return s;}
async function logoutAccount(){try{await flushEdits();await request('/logout',{method:'POST'});sessionStorage.removeItem('rotom-sheet-'+currentAccount.id);connectedSheet=null;currentAccount=null;remoteSheets=[];catalogEntries=[];catalogStamp='';applyCatalog([]);state=migrate(await readState()||blankSheet('Novo treinador'));view='account';lastPersistError=null;setSaveStatus('Salvo neste navegador');fullRender();}catch(err){toast(err.message);}}
async function seedCatalog(){try{const existing=new Set(catalogEntries.map(e=>e.id));for(const entry of seedEntries())if(!existing.has(entry.id))await request('/catalog',{method:'PUT',body:{entry,version:0}});await refreshAccount();view='author';fullRender();toast('Amostra carregada. Sua planilha não foi modificada.');}catch(err){toast(err.message);}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const actions={'account-page':async()=>{accountMessage='';if(currentAccount)await refreshAccount();view='account';fullRender();},'author-page':async()=>{await refreshCatalog(false);view='author';fullRender();},'logout-account':logoutAccount,'local-draft':openLocalDraft,'reload-remote':async()=>{if(connectedSheet)await openRemoteSheet(connectedSheet.id,true);},'seed-catalog':seedCatalog};if(b.dataset.nav==='account'){e.stopImmediatePropagation();try{if(currentAccount)await refreshAccount();view='account';fullRender();}catch(err){toast(err.message);}return;}if(b.dataset.nav==='author'){e.stopImmediatePropagation();try{await refreshCatalog(false);view='author';fullRender();}catch(err){toast(err.message);}return;}if(!actions[b.dataset.action]&&!b.dataset.openRemote)return;e.stopImmediatePropagation();b.disabled=true;try{if(b.dataset.openRemote)await openRemoteSheet(b.dataset.openRemote);else await actions[b.dataset.action]();}catch(err){toast(err.message);}finally{b.disabled=false;}},true);
document.addEventListener('submit',async e=>{const f=e.target;if(!['login-form','register-form','create-remote-form','catalog-editor-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const submit=f.querySelector('[type=submit]');submit.disabled=true;try{const v=new FormData(f);if(f.id==='catalog-editor-form'){await publishCatalog(f);return;}if(f.id==='create-remote-form'){await flushEdits();const name=String(v.get('name')).trim(),data=v.get('source')==='empty'?blankSheet(name):structuredClone(state);data.sheetName=name;const created=await request('/characters',{method:'POST',body:{name,data}});await refreshAccount();await openRemoteSheet(created.id);return;}const values=Object.fromEntries(v);if(f.id==='register-form')await request('/register',{method:'POST',body:values});currentAccount=await request('/login',{method:'POST',body:{email:values.email,password:values.password}});accountMessage='';await refreshAccount();view='account';fullRender();}catch(err){accountMessage=err.message;if(f.id==='catalog-editor-form')$('#catalog-editor-message').textContent=err.message;else toast(err.message);}finally{submit.disabled=false;}},true);
document.addEventListener('change',e=>{if(e.target.id==='catalog-editor-entry'){editorId=e.target.value;fullRender();}});
async function initializeAccount(){try{currentAccount=await request('/me');await refreshAccount();const cid=sessionStorage.getItem('rotom-sheet-'+currentAccount.id);if(cid)await openRemoteSheet(cid);else fullRender();}catch(err){if(err.status!==401&&err.status!==503)accountMessage=err.message;}}
setInterval(()=>{if(currentAccount&&document.visibilityState==='visible')refreshCatalog().catch(()=>{});},15000);
window.addEventListener('focus',()=>{if(currentAccount)refreshCatalog().catch(()=>{});});

function gimmickBadges(p){const g=gimmicks(p);return `<div class="gimmick-badges">${g.giant?`<span title="${g.giant==='gigantamax'?'Gigantamax':'Dynamax'}" aria-label="${g.giant==='gigantamax'?'Gigantamax':'Dynamax'}">${icon('spark')}<small>${g.giant==='gigantamax'?'G':'D'}</small></span>`:''}${g.tera?`<span title="Terastalização: ${escape(g.teraType)}" aria-label="Terastalização">${icon('star')}</span>`:''}${activeMega(p)?`<span title="${activeMega(p).name}" aria-label="Mega Evolução">${icon('leaf')}<small>M</small></span>`:''}</div>`;}
function gimmickPanel(p,s){const g=gimmicks(p),options=MEGAS.filter(m=>m.speciesId===p.speciesId),types=battleTypes(p,s);return `<section class="gimmick-panel"><div class="section-line"><h3>Gimmicks</h3><small>Controle da mesa</small></div><div class="gimmick-fields"><label class="field">Mega Evolução<select id="mega-form"><option value="">Forma habitual</option>${options.map(m=>`<option value="${m.id}" ${activeMega(p)?.id===m.id?'selected':''}>${m.name}</option>`).join('')}</select>${options.length?'':'<small>Sem Mega cadastrada nesta amostra.</small>'}</label><label class="field">Dynamax / Gigantamax<select id="giant-mode"><option value="">Desativado</option><option value="dynamax" ${g.giant==='dynamax'?'selected':''}>Dynamax</option><option value="gigantamax" ${g.giant==='gigantamax'?'selected':''}>Gigantamax</option></select></label><label class="field">Tera Tipo<select id="tera-type">${TYPES.map(t=>`<option ${g.teraType===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="tera-toggle"><input type="checkbox" id="tera-active" ${g.tera?'checked':''}> Terastalizar</label></div>${g.giant?`<div class="giant-turns"><span>${g.turns} turno${g.turns===1?'':'s'} · HP ×2</span><button class="btn light small" data-action="giant-turn">Avançar turno</button></div>`:''}${activeMega(p)?`<div class="mega-art-controls"><label class="btn light small upload-label">${icon('upload')} Arte personalizada da Mega<input class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" data-upload="mega" data-pokemon-id="${p.id}" data-mega-id="${activeMega(p).id}"></label>${g.megaImages[activeMega(p).id]?`<label><input type="checkbox" id="mega-custom" ${g.megaCustom?'checked':''}> Usar personalizada da Mega</label>`:''}<p class="input-note">Habilidade da Mega: ${escape(activeMega(p).ability)}. Adaptação RPG em desenvolvimento.</p></div>`:''}${g.tera?`<div class="tera-types"><span>Defesa: ${types.defense.map(type).join(' ')}</span><span>STAB +2d4: ${types.stab.map(type).join(' ')}</span></div>`:''}</section>`;}
function temporaryMoveDialog(sourceId){const p=selected(),m=byMove(sourceId),z=convertedMove(m,'z',p),max=convertedMove(m,'max',p);modal('Trocar movimento temporariamente',`<form id="temporary-move-form" data-source="${sourceId}"><p class="input-note">Habitual: ${escape(m.pt)} / ${escape(m.name)}</p><label class="field">Mostrar como<input name="name" list="temporary-move-options" autocomplete="off" required placeholder="Nome do movimento ou versão Z"><datalist id="temporary-move-options"><option value="${escape(z.name)}">Versão Z</option><option value="${escape(max.name)}">Versão Max</option>${moves.map(v=>`<option value="${escape(v.name)}">${escape(v.pt)}</option>`).join('')}</datalist></label><p class="input-note">Golpe habitual e aprendizado serão preservados. Movimentos ainda não cadastrados aparecem em desenvolvimento.</p>${modalActions('Aplicar troca')}</form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.moveInfo){e.stopImmediatePropagation();const p=selected(),base=byMove(b.dataset.moveInfo),m=effectiveMove(p,base,moves);modal(escape(m.pt),`<p class="input-note">Habitual: ${escape(base.pt)} · ${escape(m.cat)} · ${type(m.type)}</p><p class="panel-note">BP ${m.power??'—'} · Dano base ${m.pending?'Em desenvolvimento':damage(m.power)}</p><p class="reference-description">${escape(m.effect)}</p>`);}
 else if(b.dataset.tempMove){e.stopImmediatePropagation();temporaryMoveDialog(b.dataset.tempMove);}else if(b.dataset.restoreMove){e.stopImmediatePropagation();delete selected().temporaryMoves[b.dataset.restoreMove];save(true);renderDetail();}else if(b.dataset.action==='giant-turn'){e.stopImmediatePropagation();const p=selected(),g=gimmicks(p);g.turns=Math.max(0,g.turns-1);if(g.turns===0)changeGimmick(p,{giant:''},bySpecies(p.speciesId),state.trainer.level,byNature(p.nature));save(true);renderDetail();}},true);
document.addEventListener('change',e=>{const el=e.target,p=selected();if(!p)return;let patch;if(el.id==='mega-form')patch={megaId:el.value};else if(el.id==='giant-mode')patch={giant:el.value,turns:3};else if(el.id==='tera-type')patch={teraType:el.value};else if(el.id==='tera-active')patch={tera:el.checked};else if(el.id==='mega-custom')patch={megaCustom:el.checked};else return;changeGimmick(p,patch,bySpecies(p.speciesId),state.trainer.level,byNature(p.nature));save(true);renderDetail();});
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='temporary-move-form')return;e.preventDefault();e.stopImmediatePropagation();const p=selected(),source=byMove(f.dataset.source),name=String(new FormData(f).get('name')).trim(),z=convertedMove(source,'z',p),max=convertedMove(source,'max',p),match=moves.find(m=>[m.name,m.pt].some(v=>v.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')));if(!name){document.querySelector("#form-error").textContent='Informe o nome do movimento.';return;}p.temporaryMoves ||= {};p.temporaryMoves[source.id]=name.toLocaleLowerCase('pt-BR')===z.name.toLocaleLowerCase('pt-BR')?{kind:'z'}:name.toLocaleLowerCase('pt-BR')===max.name.toLocaleLowerCase('pt-BR')?{kind:'max'}:match?{kind:'catalog',moveId:match.id}:{kind:'custom',name:name.slice(0,160)};save(true);dialog.close();renderDetail();},true);

document.addEventListener('change',e=>{if(e.target.id==='permanent-variant'){const p=selected();setVariant(p,e.target.value,bySpecies(p.speciesId));normalizeHP();save(true);renderDetail();}});
let pendingSheet=null;
function heldBox(p,held){return `<section class="held-box"><button class="held" data-action="held-item">${held?(itemImage(held)?`<img src="${escape(itemImage(held))}" alt="${escape(held.pt)}">`:icon('bag')):icon('bag')}<span><small>ITEM EQUIPADO</small><strong>${held?escape(held.pt):'Equipar um item'}</strong></span>${icon('chevron')}</button>${held?`<p class="held-description">${escape(held.effect)}</p>`:''}</section>`;}
function dbGet(key){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function transferDialog(){pendingSheet=null;modal('Importar ou trocar de ficha',`<label class="btn primary upload-label">${icon('upload')} Escolher arquivo JSON<input class="visually-hidden" id="import-file" type="file" accept=".json,application/json"></label><p class="input-note">A importação inclui treinador, Pokémon, inventário, notas e imagens enviadas. A ficha atual será guardada neste navegador antes da troca.</p><div id="import-preview"></div><div id="saved-sheets"></div>`);if(!db)return;try{const list=await dbGet('backups-index')||[];if($('#saved-sheets'))$('#saved-sheets').innerHTML='<h3 style="margin-top:22px">Fichas guardadas neste navegador</h3>'+ (list.length?list.slice().reverse().map(b=>`<div class="saved-sheet"><div><strong>${escape(b.name)}</strong><small>${new Date(b.date).toLocaleString('pt-BR')}</small></div><button class="btn light small" data-load-backup="${escape(b.key)}">Abrir</button></div>`).join(''):'<p class="input-note">Nenhuma ficha guardada ainda.</p>');}catch{toast('Não foi possível consultar as fichas guardadas.');}}
function previewImport(sheet){pendingSheet=sheet;$('#import-preview').innerHTML=`<div class="panel-note" style="margin-top:18px"><strong>${escape(sheet.trainer.name)}</strong><br>${escape(sheet.trainer.className)} · Nível ${sheet.trainer.level}<br>${sheet.pokemon.length} Pokémon · ${sheet.inventory.length} itens · ${sheet.notes.length} notas</div>${button('confirm-import','Abrir esta ficha','primary')}<p class="input-note">A ficha atual será guardada automaticamente antes de abrir esta.</p>`;}
async function readImportFile(file){if(!file)return;pendingSheet=null;try{if(file.size>50*1024*1024)throw Error('Escolha uma ficha com até 50 MB.');const sheet=importSheet(JSON.parse(await file.text()));previewImport(sheet);}catch(err){if($('#import-preview'))$('#import-preview').innerHTML=`<p class="form-error">${escape(err instanceof SyntaxError?'O arquivo não contém JSON válido.':err.message)}</p>`;}}
async function loadBackup(key){try{previewImport(importSheet(await dbGet(key)));}catch{toast('Não foi possível abrir esta ficha guardada.');}}
async function confirmImport(){if(!pendingSheet)return;if(connectedSheet){toast('Abra o rascunho do navegador em Conta e fichas antes de importar outro personagem. Depois, guarde a ficha importada na sua conta.');return;}if(!db){toast('O armazenamento local precisa estar disponível para guardar a ficha atual.');return;}const next=pendingSheet;pendingSheet=null;try{clearTimeout(saveTimer);await saveQueue;const before=structuredClone(state),index=await dbGet('backups-index')||[],key='backup-'+crypto.randomUUID();index.push({key,name:before.trainer.name,date:Date.now()});await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state');store.put(before,key);store.put(index,'backups-index');store.put(next,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});state=next;normalizeHP();collectionQuery='';inventoryQuery='';collectionFilter='all';detailTab='overview';view='trainer';noteDraft={id:'',title:'',text:''};save(true);dialog.close();fullRender();toast('Ficha aberta. A anterior está guardada em Importar ficha.');}catch{pendingSheet=next;toast('A troca não foi concluída. A ficha atual foi mantida. Exporte uma cópia e tente novamente.');}}

let catalogFilters={query:'',kind:'',status:''},importBatches=[],importPreview=null,importPending=[];
function reviewFields(entry){return `${catalogCandidateUI(entry)}<div class="fields">${[['official','Dados oficiais'],['translation','Tradução'],['rpg','Adaptação RPG']].map(([key,label])=>`<label class="field">${label}<select name="review-${key}">${(key==='official'?['pending','reviewed']:['pending','draft','reviewed']).map(value=>`<option value="${value}" ${(entry.review?.[key]||'reviewed')===value?'selected':''}>${({pending:'Pendente',draft:'Rascunho',reviewed:'Revisado'})[value]}</option>`).join('')}</select></label>`).join('')}</div>${!entry.review?'<p class="input-note">Registro anterior ao controle de revisão. Os efeitos atuais serão mantidos, a menos que você escolha outro estado.</p>':''}`;}
const originalAuthorView=authorView;
authorView=function(){
 if(!currentAccount?.catalog_admin)return originalAuthorView();
 const all=catalogEntries,filtered=filterCatalog(all,catalogFilters);
 const controls=`<section class="card"><form id="catalog-filter-form"><div class="fields"><label class="field">Pesquisar<input name="query" value="${escape(catalogFilters.query)}" placeholder="Nome original ou tradução"></label><label class="field">Categoria<select name="kind"><option value="">Todas</option>${Object.entries(categoryNames).map(([k,v])=>`<option value="${k}" ${catalogFilters.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Pendências<select name="status"><option value="">Todos os estados</option>${[['official','Dados oficiais'],['translation','Tradução'],['rpg','Adaptação RPG'],['legacy','Registros anteriores']].map(([k,v])=>`<option value="${k}" ${catalogFilters.status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><button class="btn secondary" type="submit">Pesquisar</button></form><p class="input-note">${filtered.length} de ${all.length} referências</p></section>`;
 let editor;try{catalogEntries=filtered;editor=filtered.length?originalAuthorView():'<div class="card"><p>Nenhuma referência corresponde à pesquisa.</p></div>';}finally{catalogEntries=all;}
 return controls+editor+importReviewUI();
};
function importReviewUI(){const p=importPreview;return `<section class="card" style="margin-top:22px"><h2>Importação do catálogo</h2><p class="input-note">Preparar permite comparar. Publicar atualiza apenas os dados oficiais; traduções e adaptações permanecem guardadas.</p><a class="btn secondary" href="/api/catalog/template" download="modelo-catalogo.xlsx">Baixar modelo Excel</a> <label class="btn primary upload-label">Enviar planilha Excel<input class="visually-hidden" id="catalog-workbook-file" type="file" accept=".xlsx"></label><p id="workbook-read-status" role="status"></p><button class="btn light" data-catalog-action="sample">Preparar amostra antiga</button> <button class="btn light" data-catalog-action="batches">Consultar lotes</button>${importBatches.map(b=>`<div class="saved-sheet"><div><strong>${escape(b.source)}</strong><small>${new Date(b.createdAt).toLocaleString('pt-BR')} · ${b.appliedAt?'Publicado':'Em preparação'}</small></div><button class="btn light small" data-catalog-batch="${escape(b.id)}">Comparar</button></div>`).join('')}${p?`<h3>${escape(p.source)}</h3><p>${p.rows.length} registros · ${p.rows.filter(r=>r.status==='conflict').length} conflitos</p>${p.rows.map(r=>`<details class="official-reference"><summary>${escape(r.official.name)} · ${({new:'Novo',changed:'Alterado',unchanged:'Sem alteração',conflict:'Conflito',published:'Publicado'})[r.status]}</summary><p>Campos oficiais alterados: ${escape(r.changes.join(', ')||'nenhum')}</p>${r.workbook?'<p class="input-note">Textos PT/RPG e imagens entram para revisão, mesmo quando os dados oficiais não mudam.</p>':''}<div class="grid-two"><div><h4>Anterior</h4><pre>${escape(JSON.stringify(r.before,null,2))}</pre></div><div><h4>Importado</h4><pre>${escape(JSON.stringify(r.official,null,2))}</pre></div></div><details><summary>Origem, imagens e texto RPG para revisão</summary><pre>${escape(JSON.stringify(r.candidates,null,2))}</pre></details></details>`).join('')}${p.appliedAt?'<p>Lote já publicado.</p>':`<label class="override-option"><input id="approve-catalog-import" type="checkbox"> Conferi os dados oficiais deste lote.</label><button class="btn primary" data-catalog-action="publish" ${p.rows.some(r=>r.status==='conflict')?'disabled':''}>Publicar dados oficiais</button>`}`:''}${importPending.length?`<details class="official-reference"><summary>${importPending.length} linhas pendentes, fora do lote</summary>${importPending.map(r=>`<p>${escape(r.tab)} · linha ${r.row}: ${escape(r.name||'')} — ${escape(r.reason)}</p>`).join('')}</details>`:''}<p id="catalog-import-message" role="status"></p></section>`;}
document.addEventListener('submit',e=>{if(e.target.id!=='catalog-filter-form')return;e.preventDefault();const v=new FormData(e.target);catalogFilters=Object.fromEntries(v);fullRender();});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-catalog-action],[data-catalog-batch]');if(!b)return;b.disabled=true;try{
 if(b.dataset.catalogAction==='use-candidate'){const c=catalogEntries.find(e=>e.id===editorId)?.candidates,form=$('#catalog-editor-form');for(const [part,key,name]of [['translations','name','translatedName'],['translations','description','translatedDescription'],['rpg','description','rpgDescription']]){const clearing=c.clear?.includes(part+'.'+key);if(clearing||Object.hasOwn(c[part]||{},key)){form.elements[name].value=clearing?'':c[part][key];form.elements['review-'+(part==='rpg'?'rpg':'translation')].value='draft';}}toast('Textos carregados como rascunho. Confira e salve quando quiser.');return;}
 if(b.dataset.catalogBatch){importPreview=await request('/catalog/staging/'+b.dataset.catalogBatch);importPending=importPreview.pending||[];}
 if(b.dataset.catalogAction==='sample'){const staged=await request('/catalog/sample-preview',{method:'POST',body:{}});importPending=staged.pending;importPreview=await request('/catalog/staging/'+staged.id);}
 if(b.dataset.catalogAction==='batches')importBatches=await request('/catalog/staging');
 if(b.dataset.catalogAction==='publish'){if(!$('#approve-catalog-import')?.checked)throw Error('Marque que conferiu o lote antes de publicar.');await request('/catalog/staging/'+importPreview.id,{method:'POST',body:{}});importPreview=await request('/catalog/staging/'+importPreview.id);importPending=importPreview.pending||[];await refreshCatalog(false);toast('Dados oficiais publicados.');}
 fullRender();
 }catch(err){const target=$('#catalog-import-message');if(target)target.textContent=err.message;else toast(err.message);}finally{b.disabled=false;}});

function catalogCandidateUI(entry){const c=entry.candidates;if(!c)return '';return `<details class="official-reference"><summary>Propostas da última planilha publicada</summary><pre>${escape(JSON.stringify(c,null,2))}</pre><button class="btn secondary" type="button" data-catalog-action="use-candidate">Carregar textos importados no formulário</button><p class="input-note">Confira o texto e o estado antes de salvar. Links de imagem continuam candidatos.</p></details>`;}
document.addEventListener('change',async e=>{if(e.target.id!=='catalog-workbook-file')return;const file=e.target.files?.[0];if(!file)return;const status=$('#workbook-read-status');try{
 if(file.size>12*1024*1024)throw Error('Use um arquivo de até 12 MB.');status.textContent='Lendo planilha…';
 const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});
 const result=await request('/catalog/workbook',{method:'POST',body:{name:file.name,file:encoded}});importPending=result.pending||[];importPreview=result.id?await request('/catalog/staging/'+result.id):null;fullRender();$('#workbook-read-status').textContent=result.id?`${result.rows} registros preparados para comparação. Nada foi publicado.`:'Nenhum registro preparado. Preencha uma aba de dados ou confira as pendências abaixo.';
 }catch(err){status.textContent=err.message;}finally{e.target.value='';}});

function orderingSelect(id,value,category=false){return `<label class="field">Ordenar<select id="${id}">${[...(category?[['category','Categoria e nome']]:[]),['name-en','Nome original (A–Z)'],['name-pt','Nome em português (A–Z)']].map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function catalogOrderUI(){return catalogTab==='items'?orderingSelect('catalog-order',itemOrder,true):catalogTab==='abilities'?orderingSelect('catalog-order',abilityOrder):'';}
document.addEventListener('change',e=>{if(e.target.id==='catalog-order'){if(catalogTab==='items')itemOrder=e.target.value;else abilityOrder=e.target.value;$('#catalog-results').innerHTML=catalogResults();}if(e.target.id==='inventory-order'){inventoryOrder=e.target.value;$('#inventory-grid').innerHTML=inventoryCards();}});
async function startBlankDraft(){await flushEdits();const before=await readState();if(before&&db){const index=await dbGet('backups-index')||[],key='backup-'+crypto.randomUUID();index.push({key,name:before.trainer?.name||'Rascunho anterior',date:Date.now()});await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),s=tx.objectStore('state');s.put(before,key);s.put(index,'backups-index');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}connectedSheet=null;if(currentAccount)sessionStorage.removeItem('rotom-sheet-'+currentAccount.id);state=blankSheet('Novo treinador');await writeState(state);view='account';fullRender();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-archive-sheet], [data-action="blank-draft"]');if(!b)return;e.stopImmediatePropagation();try{await flushEdits();if(b.dataset.archiveSheet){if(!window.confirm('Excluir esta ficha da lista? Ela será arquivada no servidor, preservando os dados para recuperação. Exporte uma cópia se quiser guardá-la também com você.'))return;await request('/characters/'+b.dataset.archiveSheet+'/archive',{method:'POST',body:{}});if(connectedSheet?.id===b.dataset.archiveSheet){connectedSheet=null;await startBlankDraft();}await refreshAccount();fullRender();toast('Ficha arquivada. Os dados foram preservados.');}else{await startBlankDraft();toast('Rascunho vazio criado. O anterior ficou guardado em Importar ficha.');}}catch(err){toast(err.message);}},true);



function moveCategoryIcon(category){const shapes=category==='Físico'?'<path d="m15 1 2 5 7-2-3 5 7 2-8 3 2 5-7-3-5 3 1-5-8-3 7-2-3-5 6 2z" fill="currentColor"/>':category==='Especial'?'<ellipse cx="15" cy="10" rx="13" ry="8" fill="none" stroke="currentColor" stroke-width="2"/><ellipse cx="15" cy="10" rx="7" ry="4" fill="none" stroke="currentColor" stroke-width="2"/>':'<circle cx="15" cy="10" r="8" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="15" cy="10" r="3" fill="currentColor"/>';return `<span class="move-symbol" data-category="${escape(category)}" role="img" aria-label="${escape(category)}" title="${escape(category)}"><svg viewBox="0 0 30 20" aria-hidden="true">${shapes}</svg></span>`;}
function formImageGallery(p){const entries=Object.entries(p.formImages||{});if(!entries.length)return '';return `<details class="form-image-gallery"><summary>Imagens vinculadas (${entries.length})</summary><div class="inventory-grid">${entries.map(([key,url])=>{const [sid,variant,mega,giant,tera]=key.split(':'),label=[bySpecies(sid).name,variant!=='base'?(PERMANENT_VARIANTS.find(v=>v.id===variant)?.name||variant):'',mega!=='base'?(MEGAS.find(v=>v.id===mega)?.name||mega):'',giant!=='base'?giant:'',tera!=='base'?'Tera '+tera:''].filter(Boolean).join(' · ');return `<div class="form-image-card"><img src="${escape(url)}" alt="${escape(label)}" loading="lazy"><small>${escape(label)}</small><button class="btn secondary small" data-remove-form-slot="${escape(key)}">Remover vínculo</button></div>`;}).join('')}</div></details>`;}
function genderField(value='Não definido'){return `<label class="field">Gênero<select name="gender">${GENDERS.map(g=>`<option ${g===value?'selected':''}>${g}</option>`).join('')}</select></label>`;}
function attributeDice(t){return `<div class="attribute-dice">${['Corpo','Mente','Espírito'].map((name,i)=>{const sides=[0,2,4,6,8,10,12][t.attributes[i]]||0,shape=sides===2?'<circle cx="30" cy="30" r="26"/>':sides===4?'<path d="M30 3 57 55H3Z"/>':sides===6?'<rect x="5" y="5" width="50" height="50" rx="7"/>':sides===8?'<path d="m30 3 27 27-27 27L3 30Z"/>':'<path d="M16 4h28l14 26-14 26H16L2 30Z"/>';return `<div><strong>${name}</strong><svg class="attribute-die" viewBox="0 0 60 60" role="img" aria-label="${name}: ${sides?'d'+sides:'sem dado'}">${shape}<text x="30" y="${sides===4?42:35}" text-anchor="middle">${sides?'d'+sides:'—'}</text></svg></div>`;}).join('')}</div>`;}
function trainerCombat(t){const max=trainerHP();return `<section class="trainer-combat"><div class="health-head"><span>Pontos de vida</span><strong class="hp-value">${t.hp}<small> / ${max}</small></strong></div><div class="progress-bar"><span style="width:${Math.min(100,t.hp/max*100)}%"></span></div><div class="health-actions"><button class="step-btn" data-trainer-hp="-1" aria-label="Treinador: perder 1 HP">−</button><button class="step-btn" data-trainer-hp="1" aria-label="Treinador: recuperar 1 HP">+</button><button class="btn light small" data-action="trainer-hp">Dano, cura ou ajustar HP</button></div><div class="trainer-derived"><span>Defesa <strong>${Math.floor(t.survival[1]/10)}</strong></span><span>Def. especial <strong>${Math.floor(t.survival[2]/10)}</strong></span><span>Evasão <strong>${Math.floor(t.survival[3]/20)}</strong></span></div></section>`;}
function healthDialog(target){const value=target==='trainer'?state.trainer.hp:hp(selected());modal('Ajustar pontos de vida',`<form id="health-form" data-target="${target}"><p class="input-note">HP atual: ${value}. O HP pode ultrapassar o máximo.</p><label class="field">Operação<select name="mode"><option value="damage">Receber dano</option><option value="heal">Recuperar HP</option><option value="set">Definir HP atual</option></select></label><label class="field">Quantidade<input name="amount" type="number" min="0" max="999999" value="1" required></label>${modalActions('Aplicar')}</form>`);}
function confirmAction(title,text,apply){modal(title,`<p>${escape(text)}</p><div class="dialog-actions"><button class="btn secondary" data-action="close-dialog">Cancelar</button><button class="btn primary" id="confirm-update-action">Confirmar</button></div>`);$('#confirm-update-action').addEventListener('click',()=>{apply();dialog.close();save(true);fullRender();});}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.trainerHp){state.trainer.hp=healthValue(state.trainer.hp+Number(b.dataset.trainerHp));save();fullRender();return;}
 if(b.dataset.action==='mobile-menu'){modal('Navegação',`<div class="mobile-menu-list">${[['trainer','Meu treinador'],['pokemon','Pokémon'],['inventory','Inventário'],['journal','Diário'],['campaigns','Campanhas'],['catalog','Pokédex'],['account','Conta e fichas'],...(currentAccount?.catalog_admin?[['author','Editar catálogo']]:[]),['help','Sobre']].map(([id,label])=>`<button class="btn secondary" data-nav="${id}">${label}</button>`).join('')}</div>`);return;}
 if(b.dataset.action==='toggle-theme'){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('rotom-theme',dark?'dark':'light');return;}
 if(b.dataset.removeFormSlot){delete selected().formImages[b.dataset.removeFormSlot];save();renderDetail();return;}
 if(b.dataset.forgetMove){const id=b.dataset.forgetMove,p=selected();confirmAction('Apagar movimento',`Apagar ${byMove(id)?.pt||id} da memória deste Pokémon? Você poderá registrá-lo novamente.`,()=>{forgetMove(p,id);});}
 if(b.dataset.deletePokemon){const id=b.dataset.deletePokemon,p=state.retiredPokemon.find(p=>p.id===id);if(p)confirmAction('Apagar Pokémon definitivamente',`Apagar a ficha de ${p.nickname||bySpecies(p.speciesId).name}? Esta ação não pode ser desfeita pela coleção.`,()=>{deleteRetiredPokemon(state,id);});}
 if(b.dataset.itemQuantity){const entry=state.inventory.find(i=>i.id===b.dataset.itemQuantity);modal('Ajustar quantidade',`<form id="quantity-form" data-item="${escape(entry.id)}"><label class="field">Operação<select name="mode"><option value="remove">Remover unidades</option><option value="add">Adicionar unidades</option><option value="set">Definir quantidade total</option></select></label><label class="field">Quantidade<input type="number" name="amount" min="0" max="9999" value="1" required></label><p class="input-note">Unidades equipadas não podem ser removidas.</p>${modalActions('Aplicar')}</form>`);}
 if(b.dataset.renameSheet){try{await openRemoteSheet(b.dataset.renameSheet);if(connectedSheet?.id!==b.dataset.renameSheet)return;modal('Nome da ficha',`<form id="rename-sheet-form"><label class="field">Nome da ficha<input name="name" value="${escape(state.sheetName||state.trainer.name)}" maxlength="100" required></label><p class="input-note">O nome do personagem permanece igual.</p>${modalActions('Renomear')}</form>`);}catch(err){toast(err.message);}}
});
document.addEventListener('submit',e=>{const f=e.target,v=new FormData(f);if(!['health-form','quantity-form','rename-sheet-form'].includes(f.id))return;e.preventDefault();
 if(f.id==='health-form'){const target=f.dataset.target==='trainer'?state.trainer:selected();target.hp=adjustHealth(target.hp===null?hp(target):target.hp,Number(v.get('amount')),v.get('mode'));}
 if(f.id==='quantity-form'){try{adjustItemQuantity(state,f.dataset.item,Number(v.get('amount')),v.get('mode'));}catch(err){toast(err.message);return;}}
 if(f.id==='rename-sheet-form'){const name=String(v.get('name')).trim();if(!name)return;state.sheetName=name;}
 save(true);dialog.close();fullRender();});
document.documentElement.dataset.theme=localStorage.getItem('rotom-theme')||'light';

const campaignUI=createCampaignUI({request,escape,toast,modal,hosted,account:()=>currentAccount,connected:()=>connectedSheet,flush:flushEdits,refresh:refreshAccount,open:openRemoteSheet,blank:blankSheet,close:()=>dialog.close(),show:()=>{view='campaigns';fullRender();},accountPage:()=>{view='account';fullRender();},local:async()=>{connectedSheet=null;lastPersistError=null;if(currentAccount)sessionStorage.removeItem('rotom-sheet-'+currentAccount.id);state=migrate(await readState()||blankSheet('Novo treinador'));setSaveStatus('Salvo neste navegador');}});
const accountWithoutInvite=accountView;accountView=function(){return campaignUI.pendingBanner()+accountWithoutInvite();};
document.addEventListener('click',async e=>{if(!e.target.closest('[data-nav="campaigns"]'))return;e.stopImmediatePropagation();try{await campaignUI.show();}catch(error){toast(error.message);}},true);

try{db=await openDB();state=await readState();if(!state||state.version!==1){state=blankSheet('Novo treinador');normalizeHP();await writeState(state);}}catch{state=blankSheet('Novo treinador');db=null;}
state=migrate(state);state.pokeblocks ||= [];for(const p of state.pokemon){if(p.abilityId===undefined){const a=resolveAbility(p.ability?.name);p.abilityId=a?.id||'';p.abilityQuery=a?.name||p.ability?.name||'';if(p.ability?.description)p.previousAbility={...p.ability};}}normalizeHP();save();fullRender();

await initializeAccount();
if(currentAccount){try{await campaignUI.refreshContext();fullRender();}catch(error){toast(error.message);}}
if(campaignUI.hasInvite())await campaignUI.show();
